package dispatch

import "context"

// AgenticRunner runs a bounded tool loop for an Agentic dispatch. Implemented
// outside this package (in internal/server) to avoid an import cycle with
// internal/agent (which owns RunToolLoop). Given the resolved provider/model,
// it runs the loop and returns the assembled Result.
type AgenticRunner func(ctx context.Context, spec Spec, sel Selection, model string) (Result, error)

// SetAgenticRunner installs the runner that handles Agentic dispatches.
// Must be called before any Agentic Spec is dispatched; Dispatch returns an
// error if the runner is nil when an Agentic spec arrives.
func (e *Engine) SetAgenticRunner(r AgenticRunner) {
	e.agenticRunner = r
}

package dispatch

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"

	projectctx "cercano/source/server/internal/context"
	"cercano/source/server/internal/llm"
	"cercano/source/server/internal/locus"
	"cercano/source/server/internal/usage"
)

// newDispatchID mints a short random id for scoping a dispatch's provider
// session identity.
func newDispatchID() string {
	var b [8]byte
	_, _ = rand.Read(b[:])
	return hex.EncodeToString(b[:])
}

// Mode selects the dispatch execution model.
type Mode int

const (
	OneShot Mode = iota // single routed llm.Provider.Chat call
	Agentic             // bounded tool loop (not yet implemented)
)

// Spec describes a unit of work to dispatch.
type Spec struct {
	Mode                Mode
	Role                Role
	Prompt              string
	System              string
	WantsProjectContext bool
	WorkDir             string
	ConversationID      string
	Source              string
	ModelOverride       string // advisory model name within locus bounds

	// ContentTokensAvoided is the estimated cloud tokens saved by handling this
	// OneShot locally; recorded in telemetry when RecordUsage is set.
	ContentTokensAvoided int
	// RecordUsage, when true, emits one usage event (with the savings metric) to
	// the engine's usage sink for this dispatch. Co-processor capabilities set it;
	// processCoproc leaves it false so its telemetry stays MCP-side (no double-count).
	RecordUsage bool

	// Agentic-only fields (ignored for OneShot).

	// Task is the open-ended instruction for the agentic tool loop.
	Task string

	// Tools is the capability/tool name allowlist for agentic dispatch.
	// Empty means: grant R-tier tools only (least-privilege default).
	Tools []string

	// Interactive, when true, signals that a human is watching the loop
	// and event progress should be forwarded (reserved for future use).
	Interactive bool

	// MaxIterations caps the number of LLM round-trips in the loop.
	// 0 means use the package default (agent.MaxToolLoopIterations = 50).
	MaxIterations int
}

// Result holds the outcome of a dispatched call.
type Result struct {
	Text         string
	Model        string
	IsCloud      bool
	Notice       string
	InputTokens  int
	OutputTokens int

	// SubConversationID names the persisted conversation holding the
	// sub-agent's full tool loop (agentic dispatches with a store wired).
	// Empty when persistence is unavailable.
	SubConversationID string
}

// Engine routes dispatch calls to the appropriate provider.
type Engine struct {
	providersFn   func() Providers
	modeFn        func() locus.Mode
	ctxLoader     *projectctx.Loader
	modelFor      func(isCloud bool) string
	usageSink     func(usage.Usage)
	agenticRunner AgenticRunner
}

// NewEngine constructs an Engine. ctx may be nil (project context injection skipped).
//
// providersFn is called per dispatch to resolve the current candidate providers,
// so a runtime cloud-provider swap (e.g. a cloud-profile change) is honored
// without rebuilding the engine. IMPORTANT: it must return RAW (unwrapped)
// providers — the engine emits usage directly and conditionally (controlled by
// Spec.RecordUsage) so returning already-wrapped providers would double-count.
func NewEngine(providersFn func() Providers, modeFn func() locus.Mode, ctx *projectctx.Loader) *Engine {
	return &Engine{
		providersFn: providersFn,
		modeFn:      modeFn,
		ctxLoader:   ctx,
	}
}

// SetUsageSink installs a sink that receives one Usage per completed Chat call,
// labeled by Spec.Source. A nil sink disables recording (safe).
func (e *Engine) SetUsageSink(fn func(usage.Usage)) {
	e.usageSink = fn
}

// SetModelFor installs a function that maps provider tier to a model name string.
func (e *Engine) SetModelFor(fn func(isCloud bool) string) {
	e.modelFor = fn
}

// Dispatch executes spec and returns a Result.
func (e *Engine) Dispatch(ctx context.Context, spec Spec) (Result, error) {
	// 1. Select provider via locus (providers resolved fresh each dispatch).
	sel, err := Select(e.modeFn(), spec.Role, e.providersFn())
	if err != nil {
		return Result{}, err
	}

	// 2. Resolve model name.
	model := ""
	if e.modelFor != nil {
		model = e.modelFor(sel.IsCloud)
	}
	if spec.ModelOverride != "" {
		model = spec.ModelOverride
	}

	// 3a. Agentic: delegate to the installed runner (lives in internal/server
	// to avoid an import cycle with internal/agent).
	if spec.Mode == Agentic {
		if e.agenticRunner == nil {
			return Result{}, errors.New("dispatch: agentic runner not configured")
		}
		return e.agenticRunner(ctx, spec, sel, model)
	}

	// 3b. A one-shot is not part of the calling conversation: give it its own
	// provider session identity AND mark it independent so upstream bridges skip
	// lineage matching. Meridian's OpenCode adapter keys persistent session
	// state on the id — a one-message request riding the caller's id (or matched
	// by lineage) evicts the caller's session there.
	ctx = llm.WithSessionID(ctx, "oneshot-"+newDispatchID())
	ctx = llm.WithIndependentSession(ctx)

	// Optionally prepend project context (OneShot only).
	prompt := spec.Prompt
	if spec.WantsProjectContext && spec.WorkDir != "" && e.ctxLoader != nil {
		prompt = e.ctxLoader.PrependContext(spec.WorkDir, prompt)
	}

	// 4. Build chat request.
	req := llm.ChatRequest{
		Model:  model,
		System: spec.System,
		Messages: []llm.Message{
			{
				Role: llm.RoleUser,
				Blocks: []llm.Block{
					{Type: llm.BlockText, Text: prompt},
				},
			},
		},
	}

	// 5. Call provider directly; emit usage only when the caller opts in.
	resp, err := sel.Provider.Chat(ctx, req)
	if err != nil {
		return Result{}, err
	}
	if spec.RecordUsage && e.usageSink != nil {
		e.usageSink(usage.Usage{
			Source:               spec.Source,
			Model:                model,
			IsCloud:              sel.IsCloud,
			InputTokens:          resp.InputTokens,
			OutputTokens:         resp.OutputTokens,
			ContentTokensAvoided: spec.ContentTokensAvoided,
			TokenSaving:          true,
		})
	}

	// 6. Collect text blocks.
	var text string
	for _, b := range resp.Blocks {
		if b.Type == llm.BlockText {
			text += b.Text
		}
	}

	// 7. Return result.
	return Result{
		Text:         text,
		Model:        model,
		IsCloud:      sel.IsCloud,
		Notice:       sel.Notice,
		InputTokens:  resp.InputTokens,
		OutputTokens: resp.OutputTokens,
	}, nil
}

package dispatch

import (
	"fmt"

	"cercano/source/server/internal/llm"
	"cercano/source/server/internal/locus"
)

// Role selects which locus policy governs the choice.
type Role int

const (
	RoleMain   Role = iota // main agentic work: mode.Main()
	RoleCoproc             // co-processor / one-shot work: mode.Coproc()
)

// Providers holds the candidate providers; either may be nil/absent.
type Providers struct {
	Cloud llm.Provider
	Open  llm.Provider
}

// Selection is the resolved provider for a unit of work.
type Selection struct {
	Provider llm.Provider
	IsCloud  bool
	FellBack bool
	Notice   string
}

// Select resolves a provider under the given locus mode and role. Locus is the
// hard governor: cloud_only/local_only never cross tiers; preferred/fallback
// are honored only when the resolution permits crossing.
func Select(mode locus.Mode, role Role, p Providers) (Selection, error) {
	res := mode.Main()
	if role == RoleCoproc {
		res = mode.Coproc()
	}
	pick := func(t locus.Tier) llm.Provider {
		if t == locus.TierCloud {
			if p.Cloud != nil && p.Cloud.Name() != "NONE" {
				return p.Cloud
			}
			return nil
		}
		return p.Open
	}
	label := "main"
	if role == RoleCoproc {
		label = "co-processor"
	}
	if prov := pick(res.Preferred); prov != nil {
		return Selection{Provider: prov, IsCloud: res.Preferred == locus.TierCloud}, nil
	}
	if res.CrossAllowed {
		if prov := pick(res.Fallback); prov != nil {
			return Selection{
				Provider: prov,
				IsCloud:  res.Fallback == locus.TierCloud,
				FellBack: true,
				Notice:   fmt.Sprintf("locus: preferred %s tier unavailable — ran on %s (%s)", label, res.Fallback, prov.Name()),
			}, nil
		}
	}
	return Selection{}, fmt.Errorf("locus mode %q: no %s provider available for %s work", mode, res.Preferred, label)
}

// Package protocols is the single source for Cercano's workflow protocols.
// One protocol document feeds three outputs: the always-on steering block
// (Trigger lines), the get_protocol capability (Body), and generated SKILL.md
// files for host discovery. Ported from the hardwAIr_hckr "Dave" core skills
// and the generic khalkulo/workflow decision protocol.
package protocols

import "sort"

// Domain separates generic protocols from domain-specific ones so the default
// steering set can exclude hardware protocols.
type Domain string

const (
	DomainCore     Domain = "core"
	DomainHardware Domain = "hardware"
)

// Protocol is one workflow discipline.
type Protocol struct {
	Name        string // kebab-case id, e.g. "design-decisions"
	Description string // one-line, for skill discovery
	Domain      Domain
	Trigger     string // one-line always-on rule (feeds the steering block)
	Body        string // the full protocol markdown (pulled on demand)
}

// Builtins returns the built-in protocol catalog, sorted by name.
func Builtins() []Protocol {
	out := append([]Protocol(nil), builtinProtocols...)
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// Get returns a protocol by name.
func Get(name string) (Protocol, bool) {
	for _, p := range builtinProtocols {
		if p.Name == name {
			return p, true
		}
	}
	return Protocol{}, false
}

// ForDomain returns protocols in the given domain, sorted by name.
func ForDomain(d Domain) []Protocol {
	var out []Protocol
	for _, p := range Builtins() {
		if p.Domain == d {
			out = append(out, p)
		}
	}
	return out
}

package protocols

import "strings"

// plainEnglishRules are the always-on steering rules. Kept terse and concrete.
const plainEnglishRules = `Communication and working rules:
- Write in plain English. Present decisions, options, and trade-offs as clear prose a colleague would use — not terse model shorthand or jargon. Spell out acronyms the first time.
- When you face a choice or report a trade-off, lay out the real alternatives and your reasoning, then recommend one.
- After you finish a solved unit of work, commit it with the checkpoint tool (a clear conventional-commit subject + body). Never push unless explicitly asked.`

// SteeringBlock assembles the always-on steering text: the fixed plain-English
// rules followed by one trigger line per protocol. The block is generated from
// the protocols themselves so the rules and the library never drift.
func SteeringBlock(ps []Protocol) string {
	var b strings.Builder
	b.WriteString(plainEnglishRules)
	if len(ps) > 0 {
		b.WriteString("\n\nWorkflow protocols — when one of these applies, pull the full protocol with the get_protocol tool and follow it:")
		for _, p := range ps {
			b.WriteString("\n- ")
			b.WriteString(p.Trigger)
		}
	}
	return b.String()
}

package watchdog

import (
	"context"
	"crypto/sha256"
	"fmt"
	"log"
	"sync"
	"time"
)

// Mode controls how the Watchdog responds to a first-time violation.
type Mode string

const (
	ModeChallenge Mode = "challenge-and-justify"
	ModeStrict    Mode = "strict"
)

// Decision is the result returned by Gate.
type Decision struct {
	Action    string // "allow" | "challenge" | "block" | "escalate"
	Protocol  string
	Challenge string
	// Revise carries the violated check's corrective instruction (Verdict.Revise).
	Revise string
}

// Config tunes Watchdog behaviour.
// EscalateAfter: number of times the same key must be seen before escalation.
// Zero means default (2).
// CheckTimeout bounds each Gate call's check evaluation. Zero means default
// (15s). Supervision must never wedge the supervised: a turn-end gate runs
// after the reply has already streamed, so an unbounded check against a sick
// model lane holds the stream open and the client queues everything.
type Config struct {
	Mode          Mode
	EscalateAfter int
	CheckTimeout  time.Duration
}

// convState holds per-conversation state.
type convState struct {
	justified      map[string]bool
	counts         map[string]int
	lastChallenged string // key most recently challenged or escalated for this conversation
}

// Watchdog runs a set of Checks against agent Actions and enforces a
// per-conversation challenge/block/escalate policy.
type Watchdog struct {
	cfg           Config
	checks        []Check
	oneShot       OneShotFunc
	escalateAfter int
	checkTimeout  time.Duration

	mu    sync.Mutex
	convs map[string]*convState

	echo func(thread, text string) // optional; nil means silent
}

// SetEcho registers a callback that is called on watchdog interventions and
// justify overrides. thread is "watchdog" or "main". Synchronized with w.mu,
// so it may be called on a live Watchdog; note the callback is global to the
// Watchdog, not per-conversation — under concurrent conversations, echo lines
// from all of them reach the same callback.
func (w *Watchdog) SetEcho(fn func(thread, text string)) {
	w.mu.Lock()
	w.echo = fn
	w.mu.Unlock()
}

// emitEcho calls the echo callback if one is registered. It briefly acquires
// w.mu to snapshot the callback, so callers must NOT hold w.mu (sync.Mutex is
// not reentrant). The callback itself runs outside the lock, so it can never
// deadlock the watchdog.
func (w *Watchdog) emitEcho(thread, text string) {
	w.mu.Lock()
	fn := w.echo
	w.mu.Unlock()
	if fn != nil {
		fn(thread, text)
	}
}

// New creates a ready Watchdog.
func New(cfg Config, checks []Check, oneShot OneShotFunc) *Watchdog {
	ea := cfg.EscalateAfter
	if ea <= 0 {
		ea = 2
	}
	ct := cfg.CheckTimeout
	if ct <= 0 {
		ct = 15 * time.Second
	}
	return &Watchdog{
		cfg:           cfg,
		checks:        checks,
		oneShot:       oneShot,
		escalateAfter: ea,
		checkTimeout:  ct,
		convs:         make(map[string]*convState),
	}
}

// keyFor returns the action-identity key for dedup / justify tracking.
// Format: protocol + "|" + toolName + "|" + first-12-hex-chars-of-sha256(identity).
// For turn_end actions the identity is the reply text; for tool_call it is ToolArgs.
func keyFor(protocol string, a Action) string {
	identity := a.ToolArgs
	if a.Kind == "turn_end" {
		identity = []byte(a.Text)
	}
	sum := sha256.Sum256(identity)
	return fmt.Sprintf("%s|%s|%x", protocol, a.ToolName, sum[:6]) // 6 bytes = 12 hex chars
}

// getOrCreate returns the convState for the given conversation, creating it lazily.
// Caller must hold w.mu.
func (w *Watchdog) getOrCreate(conversationID string) *convState {
	cs, ok := w.convs[conversationID]
	if !ok {
		cs = &convState{
			justified: make(map[string]bool),
			counts:    make(map[string]int),
		}
		w.convs[conversationID] = cs
	}
	return cs
}

// Gate evaluates all checks against action a and returns a Decision.
func (w *Watchdog) Gate(ctx context.Context, conversationID string, a Action) Decision {
	// Bound the whole evaluation: a supervision verdict that takes longer than
	// checkTimeout is useless, and on the turn_end path an unbounded check
	// holds the client's stream open behind it. Deadline expiry rides the
	// existing fail-open error path below.
	ctx, cancel := context.WithTimeout(ctx, w.checkTimeout)
	defer cancel()
	// Run checks; fail-open on error.
	var violation *Verdict
	for _, ch := range w.checks {
		if !ch.Applies(a) {
			continue
		}
		v, err := ch.Evaluate(ctx, a, w.oneShot)
		if err != nil {
			log.Printf("watchdog: check %q error (fail-open): %v", ch.Name(), err)
			continue
		}
		if v.Violation {
			vCopy := v
			violation = &vCopy
			break
		}
	}

	if violation == nil {
		return Decision{Action: "allow"}
	}

	key := keyFor(violation.Protocol, a)

	w.mu.Lock()
	cs := w.getOrCreate(conversationID)
	if cs.justified[key] {
		w.mu.Unlock()
		return Decision{Action: "allow", Protocol: violation.Protocol}
	}
	cs.counts[key]++
	count := cs.counts[key]
	isStrict := w.cfg.Mode == ModeStrict
	escalate := count >= w.escalateAfter
	if escalate || !isStrict {
		cs.lastChallenged = key
	}
	w.mu.Unlock()

	if escalate {
		w.emitEcho("watchdog", fmt.Sprintf("[escalate] %s: %s", violation.Protocol, violation.Challenge))
		return Decision{Action: "escalate", Protocol: violation.Protocol, Challenge: violation.Challenge, Revise: violation.Revise}
	}
	if isStrict {
		w.emitEcho("watchdog", fmt.Sprintf("[block] %s: %s", violation.Protocol, violation.Challenge))
		return Decision{Action: "block", Protocol: violation.Protocol, Challenge: violation.Challenge, Revise: violation.Revise}
	}
	w.emitEcho("watchdog", fmt.Sprintf("[challenge] %s: %s", violation.Protocol, violation.Challenge))
	return Decision{Action: "challenge", Protocol: violation.Protocol, Challenge: violation.Challenge, Revise: violation.Revise}
}

// recordJustify marks key as justified for the given conversation so Gate
// will allow future matching actions without re-challenging.
func (w *Watchdog) recordJustify(conversationID, key string) {
	w.mu.Lock()
	defer w.mu.Unlock()
	cs := w.getOrCreate(conversationID)
	cs.justified[key] = true
}

// lastChallengedKey returns the key most recently challenged or escalated for
// the given conversation, or "" if none.
func (w *Watchdog) lastChallengedKey(conversationID string) string {
	w.mu.Lock()
	defer w.mu.Unlock()
	cs, ok := w.convs[conversationID]
	if !ok {
		return ""
	}
	return cs.lastChallenged
}

package builtins

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"

	"cercano/source/server/internal/capabilities"
	"cercano/source/server/internal/dispatch"
)

type dispatchCap struct{}

// Dispatch constructs the dispatch capability.
func Dispatch() capabilities.Capability { return dispatchCap{} }

func (dispatchCap) Name() string            { return "dispatch" }
func (dispatchCap) Tier() capabilities.Tier { return capabilities.TierW }
func (dispatchCap) Surfaces() capabilities.Surface {
	return capabilities.SurfaceAgent | capabilities.SurfaceMCP
}
func (dispatchCap) Description() string {
	return "Run a sub-agent: hand off an open-ended task to a bounded tool-use loop over a granted set of tools (default: read-only tools). Returns the sub-agent's final result. Tool names passed in `tools` must be the plain registered names (e.g. \"Read\", \"Glob\") — do NOT include any host/MCP prefix like \"mcp__oc__\"."
}
func (dispatchCap) Schema() capabilities.Schema {
	return capabilities.Schema(`{
		"type": "object",
		"required": ["task"],
		"properties": {
			"task":            {"type": "string", "description": "Open-ended instruction for the sub-agent tool loop."},
			"tools":           {"type": "array", "items": {"type": "string"}, "description": "Tool or capability names to grant, using the plain registered names (e.g. \"Read\", \"Glob\", \"Grep\", \"Bash\") — no host or MCP prefix. Omit to default to read-only tools."},
			"conversation_id": {"type": "string", "description": "Optional conversation ID to associate with this dispatch."}
		}
	}`)
}

type dispatchArgs struct {
	Task           string   `json:"task"`
	Tools          []string `json:"tools"`
	ConversationID string   `json:"conversation_id"`
}

func (dispatchCap) Execute(ctx context.Context, call *capabilities.Call) (*capabilities.Result, error) {
	var a dispatchArgs
	if err := json.Unmarshal(call.Args, &a); err != nil {
		return nil, fmt.Errorf("dispatch: parse args: %w", err)
	}
	if a.Task == "" {
		return nil, errors.New("dispatch: 'task' is required")
	}
	if call.Svc.Dispatch == nil {
		return nil, errors.New("dispatch: engine not available")
	}
	res, err := call.Svc.Dispatch(ctx, dispatch.Spec{
		Mode:           dispatch.Agentic,
		Role:           dispatch.RoleMain,
		Task:           a.Task,
		Tools:          a.Tools,
		WorkDir:        call.WorkDir,
		ConversationID: a.ConversationID,
		Interactive:    false,
	})
	if err != nil {
		return nil, err
	}
	return capabilities.NewTextResult(res.Text), nil
}

package builtins

import (
	"cercano/source/server/internal/capabilities"
	"cercano/source/server/internal/capabilities/mcpadapter"
)

func init() {
	capabilities.RegisterMCPCatalogSource(func() []mcpadapter.CapMeta {
		reg := capabilities.NewRegistry(capabilities.Services{})
		Register(reg)
		syns := CapabilitySynonyms()
		var out []mcpadapter.CapMeta
		for _, c := range reg.ForSurface(capabilities.SurfaceMCP) {
			out = append(out, mcpadapter.CapMeta{
				Name:        c.Name(),
				Description: c.Description(),
				Schema:      c.Schema(),
				Synonyms:    syns[c.Name()],
			})
		}
		return out
	})
}

// Register adds every built-in capability to reg.
func Register(reg *capabilities.Registry) {
	// R-tier
	reg.MustRegister(ReadFile())
	reg.MustRegister(ListDir())
	reg.MustRegister(StatFile())
	reg.MustRegister(Glob())
	reg.MustRegister(Grep())
	reg.MustRegister(GitStatus())
	reg.MustRegister(GitLog())
	reg.MustRegister(GetProtocol())
	reg.MustRegister(Summarize())
	reg.MustRegister(Extract())
	reg.MustRegister(Classify())
	reg.MustRegister(Explain())
	reg.MustRegister(Review())
	reg.MustRegister(Fetch())
	reg.MustRegister(Research())
	reg.MustRegister(DeepResearch())
	reg.MustRegister(Local())
	// W-tier
	reg.MustRegister(WriteFile())
	reg.MustRegister(EditFile())
	reg.MustRegister(RunCommand())
	reg.MustRegister(GitAdd())
	reg.MustRegister(GitCommit())
	reg.MustRegister(Dispatch())
	reg.MustRegister(GitWorktree())
	reg.MustRegister(Checkpoint())
	reg.MustRegister(GitSquash())
	reg.MustRegister(GitBisect())
	// X-tier
	reg.MustRegister(RmFile())
	reg.MustRegister(GitPush())
	reg.MustRegister(GitResetHard())
	reg.MustRegister(GitRecover())
	reg.MustRegister(GitLand())
}

// AgentAliases maps canonical capability names to standalone display names —
// pure renames applied only on the standalone surface (e.g. so an LLM trained
// on Claude Code conventions reaches for "Read" instead of "read_file"). The
// canonical name is replaced by the display name in the standalone catalog;
// nothing is registered under the canonical name on that surface.
//
// For alternate names that should coexist with the canonical name on both
// surfaces, see CapabilitySynonyms.
func AgentAliases() map[string]string {
	return map[string]string{
		"read_file":   "Read",
		"list_dir":    "LS",
		"glob":        "Glob",
		"grep":        "Grep",
		"write_file":  "Write",
		"edit_file":   "Edit",
		"run_command": "Bash",
		// stat_file, git_*, rm_file keep their canonical names as display names.
	}
}

// CapabilitySynonyms maps a capability's canonical name to alternate names it
// should ALSO be discoverable under, on both the standalone and MCP surfaces.
// Unlike AgentAliases (a pure rename), synonyms are additive: the capability
// remains discoverable under its canonical name AND every synonym, so callers
// reaching for either name find the tool.
//
// Motivating case: `dispatch` — Cercano's canonical name — is what host models
// like Claude reach for as "workflow". Registering both means the tool is
// found no matter which name the model tries first.
func CapabilitySynonyms() map[string][]string {
	return map[string][]string{
		"dispatch": {"workflow"},
	}
}

package builtins

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"cercano/source/server/internal/capabilities"
	"cercano/source/server/internal/protocols"
)

type getProtocolCap struct{}

// GetProtocol constructs the get_protocol capability: returns a workflow
// protocol's full body by name.
func GetProtocol() capabilities.Capability { return getProtocolCap{} }

func (getProtocolCap) Name() string            { return "get_protocol" }
func (getProtocolCap) Tier() capabilities.Tier { return capabilities.TierR }
func (getProtocolCap) Surfaces() capabilities.Surface {
	return capabilities.SurfaceAgent | capabilities.SurfaceMCP
}
func (getProtocolCap) Description() string {
	return "Return the full text of a Cercano workflow protocol by name (e.g. design-decisions, systematic-debugging, verification-strategy, compute-before-simulate). Pull a protocol when its trigger applies, then follow it."
}
func (getProtocolCap) Schema() capabilities.Schema {
	return capabilities.Schema(`{"type":"object","required":["name"],"properties":{"name":{"type":"string","description":"Protocol name, e.g. design-decisions."}}}`)
}

type getProtocolArgs struct {
	Name string `json:"name"`
}

func (getProtocolCap) Execute(_ context.Context, call *capabilities.Call) (*capabilities.Result, error) {
	var a getProtocolArgs
	if err := json.Unmarshal(call.Args, &a); err != nil {
		return nil, fmt.Errorf("get_protocol: parse args: %w", err)
	}
	if a.Name == "" {
		return nil, errors.New("get_protocol: name is required")
	}
	p, ok := protocols.Get(a.Name)
	if !ok {
		var names []string
		for _, b := range protocols.Builtins() {
			names = append(names, b.Name)
		}
		return nil, fmt.Errorf("get_protocol: unknown protocol %q; available: %s", a.Name, strings.Join(names, ", "))
	}
	return capabilities.NewTextResult(p.Body), nil
}

