func (s *Server) preCheckModelForResearch(ctx context.Context) string {
	// Probe the current model name with a minimal request
	resp, err := s.grpcClient.ProcessRequest(ctx, &proto.ProcessRequestRequest{
		Input:  "hi",
		Coproc: true,
