// OpenAI-compatible client pointed at that instance — llama-server exposes
// /v1/chat/completions natively. This is what lets the dispatch engine's open
// lane (watchdog checks, coproc capabilities, sub-agent loops under a local
// locus) follow the configured runtime instead of silently requiring an
// Ollama daemon.
type LLMProvider struct {
	eng *Engine
}

// NewLLMProvider wraps eng as a native llm.Provider.
func NewLLMProvider(eng *Engine) *LLMProvider { return &LLMProvider{eng: eng} }

func (p *LLMProvider) Name() string { return "llama_server" }

func (p *LLMProvider) Capabilities() llm.Capabilities {
	return llm.Capabilities{SupportsTools: true}
}

func (p *LLMProvider) Chat(ctx context.Context, req llm.ChatRequest) (llm.ChatResponse, error) {
	c, req, err := p.clientFor(ctx, req)
	if err != nil {
		return llm.ChatResponse{}, err
	}
	return c.Chat(ctx, req)
}

func (p *LLMProvider) StreamChat(ctx context.Context, req llm.ChatRequest) (llm.StreamReader, error) {
	c, req, err := p.clientFor(ctx, req)
	if err != nil {
		return nil, err
	}
	return c.StreamChat(ctx, req)
}

// clientFor resolves the instance endpoint for req.Model and returns a client
// bound to it, plus the request rewritten to the resolved model id (llama-server
// serves one model per instance; the id in the request is informational).
func (p *LLMProvider) clientFor(ctx context.Context, req llm.ChatRequest) (*openai.Client, llm.ChatRequest, error) {
	endpoint, model, err := p.eng.endpointFor(ctx, req.Model)
	if err != nil {
		return nil, req, err
	}
	if model == "" {
		model = "default"
	}
	req.Model = model
	c := openai.NewClient(openai.Config{
		BaseURL: strings.TrimRight(endpoint, "/") + "/v1",
		Model:   model,
	})
	return c, req, nil
}

package llamaserver

import (
	"context"
	"net/http"
	"net/http/httptest"
	"testing"

	"cercano/source/server/internal/llm"
	"cercano/source/server/internal/localruntime"
)

// TestLLMProviderChat drives the native-provider adapter end to end: resolve
// the warm instance for the requested model, POST /v1/chat/completions on its
// endpoint, translate the response into llm blocks.
func TestLLMProviderChat(t *testing.T) {
	var sawPath string
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		sawPath = r.URL.Path
		w.Header().Set("Content-Type", "application/json")
		_, _ = w.Write([]byte(`{
			"choices": [{"message": {"role": "assistant", "content": "verdict: fine"}, "finish_reason": "stop"}],
			"usage": {"prompt_tokens": 7, "completion_tokens": 3}
		}`))
	}))
	defer server.Close()

	manager := &fakeRuntimeManager{
		models: []localruntime.ModelRecord{{
			ID:           "llama_server:phi4",
			DisplayName:  "Phi 4 Mini Instruct",
			Runtime:      runtimeName,
			Path:         "/models/phi-4-mini-instruct.gguf",
			SupportsChat: true,
		}},
		instances: []localruntime.InstanceRecord{{
			ID:       "inst-chat",
			Runtime:  runtimeName,
			ModelID:  "llama_server:phi4",
			State:    localruntime.StateRunning,
			Endpoint: server.URL,
		}},
	}
	prov := NewLLMProvider(NewEngine(manager))

	// Resolution by display name — model tiers written from the settings UI
	// carry display names; the adapter must resolve them like every other
	// llama-server model reference.
	resp, err := prov.Chat(context.Background(), llm.ChatRequest{
		Model: "Phi 4 Mini Instruct",
		Messages: []llm.Message{
			{Role: llm.RoleUser, Blocks: []llm.Block{{Type: llm.BlockText, Text: "judge this"}}},
		},
	})
	if err != nil {
		t.Fatalf("Chat: %v", err)
	}
	if sawPath != "/v1/chat/completions" {
		t.Errorf("path = %q, want /v1/chat/completions", sawPath)
	}
	if len(resp.Blocks) == 0 || resp.Blocks[0].Text != "verdict: fine" {
		t.Errorf("blocks = %+v, want text 'verdict: fine'", resp.Blocks)
	}
	if resp.InputTokens != 7 || resp.OutputTokens != 3 {
		t.Errorf("tokens = %d/%d, want 7/3", resp.InputTokens, resp.OutputTokens)
	}
}

func TestLLMProviderName(t *testing.T) {
	prov := NewLLMProvider(NewEngine(nil))
	if prov.Name() != "llama_server" {
		t.Errorf("Name() = %q", prov.Name())
	}
	if !prov.Capabilities().SupportsTools {
		t.Error("llama-server provider must advertise tool support")
	}
}

