package watchdog

import (
	"context"
	"fmt"
	"strings"

	"cercano/source/server/internal/llm"
)

type debugLoopCheck struct{}

// DebugLoopCheck flags edits made to fix a bug/test failure with no evidence of
// the systematic-debugging loop in the recent transcript.
func DebugLoopCheck() Check { return debugLoopCheck{} }

func (debugLoopCheck) Name() string { return "debug-loop" }

var editTools = map[string]bool{"edit_file": true, "write_file": true, "rm_file": true, "git_reset_hard": true}

func (debugLoopCheck) Applies(a Action) bool {
	return a.Kind == "tool_call" && editTools[a.ToolName]
}

func (debugLoopCheck) Evaluate(ctx context.Context, a Action, oneShot OneShotFunc) (Verdict, error) {
	if oneShot == nil {
		return Verdict{Protocol: "debug-loop"}, nil // no model → fail open
	}
	prompt := buildDebugLoopPrompt(a)
	out, err := oneShot(ctx, prompt)
	if err != nil {
		return Verdict{}, err
	}
	return parseVerdict("debug-loop", out), nil
}

func buildDebugLoopPrompt(a Action) string {
	var b strings.Builder
	b.WriteString("You are a supervisor enforcing the systematic-debugging protocol.\n")
	b.WriteString("The agent is about to run a code-mutating tool. Judge ONLY whether it is fixing a bug or test failure WITHOUT evidence in the recent transcript of the debug loop: reducing to the smallest failing case, observing actual data/output, and confirming the root cause with a probe. Refactors, new features, and edits with clear prior evidence are NOT violations.\n\n")
	fmt.Fprintf(&b, "Proposed action: %s %s\n\n", a.ToolName, string(a.ToolArgs))
	b.WriteString("Recent transcript:\n")
	b.WriteString(transcriptTail(a.Transcript, 12))
	b.WriteString("\n\nRespond EXACTLY:\nVIOLATION: yes|no\nCHALLENGE: <one line, only if yes>\n")
	return b.String()
}

// transcriptTail renders the last n messages as plain text for the prompt.
func transcriptTail(msgs []llm.Message, n int) string {
	if len(msgs) > n {
		msgs = msgs[len(msgs)-n:]
	}
	var b strings.Builder
	for _, m := range msgs {
		for _, blk := range m.Blocks {
			if blk.Type == llm.BlockText && strings.TrimSpace(blk.Text) != "" {
				fmt.Fprintf(&b, "[%s] %s\n", m.Role, strings.TrimSpace(blk.Text))
			}
		}
	}
	return b.String()
}

// Package watchdog — worktreefirst.go: enforces the worktree-first protocol
// by blocking `git checkout -b` and `git switch -c` when they'd land in the
// shared root workspace. Agents are steered to the git_worktree tool instead.
//
// The check is deterministic — no LLM required. Applies fires whenever the
// pattern is present in a run_command tool call; Evaluate returns a fixed
// violation with a challenge that names the escape hatch (the git_worktree
// tool) and points at the protocol body for the rationale.
package watchdog

import (
	"context"
	"encoding/json"
	"regexp"
	"strings"
)

type worktreeFirstCheck struct{}

// WorktreeFirstCheck refuses raw branch-creation shell commands so agents
// use the git_worktree tool instead.
func WorktreeFirstCheck() Check { return worktreeFirstCheck{} }

func (worktreeFirstCheck) Name() string { return "worktree-first" }

// runCommandToolName is the canonical name of the shell-execution
// capability inside Cercano's tool registry. Kept as a constant so the
// Applies filter stays legible.
const runCommandToolName = "run_command"

// branchCreatePattern matches raw shell forms that create a new branch:
//   - git checkout -b <name>
//   - git checkout -B <name>
//   - git switch -c <name>
//   - git switch -C <name>
//
// Whitespace between tokens is flexible; the pattern anchors on word
// boundaries so `-branch` (a partial match) doesn't trip it.
var branchCreatePattern = regexp.MustCompile(`\bgit\s+(?:checkout\s+-B?|switch\s+-C?)\b`)

// runCommandInput mirrors the Input struct of the run_command capability so
// we can decode ToolArgs without importing the builtin package (which would
// cycle with the server package that owns Gate).
type runCommandInput struct {
	Cmd []string `json:"cmd"`
	Cwd string   `json:"cwd"`
}

func (worktreeFirstCheck) Applies(a Action) bool {
	if a.Kind != "tool_call" || a.ToolName != runCommandToolName {
		return false
	}
	var in runCommandInput
	if err := json.Unmarshal(a.ToolArgs, &in); err != nil {
		return false
	}
	// Flatten into one effective command line so both direct
	// invocations (`git checkout -b …`) and shell wrappers
	// (`bash -lc "git checkout -b …"`) both match.
	line := strings.Join(in.Cmd, " ")
	return branchCreatePattern.MatchString(line)
}

// Evaluate returns a fixed violation whenever Applies matched. The challenge
// text names the escape hatch (the git_worktree tool) and points at the
// protocol body so the agent knows where to look for the full rationale.
func (worktreeFirstCheck) Evaluate(_ context.Context, _ Action, _ OneShotFunc) (Verdict, error) {
	return Verdict{
		Violation: true,
		Protocol:  "worktree-first",
		Challenge: "Creating a branch in the shared root workspace is a worktree-first protocol violation. Use the git_worktree tool instead. Run get_protocol('worktree-first') for the full rule.",
	}, nil
}

package watchdog

import (
	"context"
	"strings"
)

type followThroughCheck struct{}

// FollowThroughCheck flags a final reply that commits to performing an
// imminent action ("let me check…", "running it now") and then ends the turn
// without doing it. The turn ends the moment such a reply is emitted with no
// tool calls, so the promised work can never happen — the empty promise reads
// as progress while nothing runs.
func FollowThroughCheck() Check { return followThroughCheck{} }

func (followThroughCheck) Name() string { return "follow-through" }

func (followThroughCheck) Applies(a Action) bool {
	return a.Kind == "turn_end" && strings.TrimSpace(a.Text) != ""
}

func (followThroughCheck) Evaluate(ctx context.Context, a Action, oneShot OneShotFunc) (Verdict, error) {
	if oneShot == nil {
		return Verdict{Protocol: "follow-through"}, nil // fail open
	}
	out, err := oneShot(ctx, buildFollowThroughPrompt(a.Text))
	if err != nil {
		return Verdict{}, err
	}
	v := parseVerdict("follow-through", out)
	if v.Violation {
		v.Revise = "Perform the action you announced NOW, in this same turn, using tool calls — or state plainly that you are not doing it and why"
	}
	return v, nil
}

func buildFollowThroughPrompt(text string) string {
	var b strings.Builder
	b.WriteString("You are a supervisor enforcing follow-through for an autonomous coding agent.\n")
	b.WriteString("The reply below is the agent's FINAL message of its turn — after sending it, the agent stops and waits for the user. Any action it promises to take next therefore never happens.\n")
	b.WriteString("Judge ONLY whether the reply commits to performing an imminent action itself and then stops — e.g. it ends with \"Let me check…\", \"Running it now\", \"Doing it now —\", \"I'll go read the log\", \"Actually running the probe now:\" with nothing after.\n")
	b.WriteString("NOT violations: reporting completed work, answering a question, asking the user something, proposing options for the user to choose, or describing future work that is contingent on the user's approval.\n\n")
	b.WriteString("Reply:\n")
	b.WriteString(text)
	b.WriteString("\n\nRespond EXACTLY:\nVIOLATION: yes|no\nCHALLENGE: <one line, only if yes>\n")
	return b.String()
}

