// lastAssistantEntry returns the last entry with RoleAssistant, or nil.
func (c *chatView) lastAssistantEntry() *Entry {
	for i := len(c.entries) - 1; i >= 0; i-- {
		if c.entries[i].Role == RoleAssistant {
			return c.entries[i]
		}
