// Package watchdog — worktreefirst.go: enforces the worktree-first protocol
// by blocking `git checkout -b` and `git switch -c` when they'd land in the
// shared root workspace. Agents are steered to the git_worktree tool instead.
//
// The check is deterministic — no LLM required. Applies fires whenever the
// pattern is present in a run_command tool call; Evaluate returns a fixed
// violation with a challenge that names the escape hatch (the git_worktree
// tool) and points at the protocol body for the rationale.
package watchdog

import (
	"context"
	"encoding/json"
	"regexp"
	"strings"
)

type worktreeFirstCheck struct{}

// WorktreeFirstCheck refuses raw branch-creation shell commands so agents
// use the git_worktree tool instead.
func WorktreeFirstCheck() Check { return worktreeFirstCheck{} }

func (worktreeFirstCheck) Name() string { return "worktree-first" }

// runCommandToolName is the canonical name of the shell-execution
// capability inside Cercano's tool registry. Kept as a constant so the
// Applies filter stays legible.
const runCommandToolName = "run_command"

// branchCreatePattern matches raw shell forms that create a new branch:
//   - git checkout -b <name>
//   - git checkout -B <name>
//   - git switch -c <name>
//   - git switch -C <name>
//
// Whitespace between tokens is flexible; the pattern anchors on word
// boundaries so `-branch` (a partial match) doesn't trip it.
var branchCreatePattern = regexp.MustCompile(`\bgit\s+(?:checkout\s+-B?|switch\s+-C?)\b`)

// runCommandInput mirrors the Input struct of the run_command capability so
// we can decode ToolArgs without importing the builtin package (which would
// cycle with the server package that owns Gate).
type runCommandInput struct {
	Cmd []string `json:"cmd"`
	Cwd string   `json:"cwd"`
}

func (worktreeFirstCheck) Applies(a Action) bool {
	if a.Kind != "tool_call" || canonical(a.ToolName) != runCommandToolName {
		return false
	}
	var in runCommandInput
	if err := json.Unmarshal(a.ToolArgs, &in); err != nil {
		return false
	}
	// Flatten into one effective command line so both direct
	// invocations (`git checkout -b …`) and shell wrappers
	// (`bash -lc "git checkout -b …"`) both match.
	line := strings.Join(in.Cmd, " ")
	return branchCreatePattern.MatchString(line)
}

// Evaluate returns a fixed violation whenever Applies matched. The challenge
// text names the escape hatch (the git_worktree tool) and points at the
// protocol body so the agent knows where to look for the full rationale.
func (worktreeFirstCheck) Evaluate(_ context.Context, _ Action, _ OneShotFunc) (Verdict, error) {
	return Verdict{
		Violation: true,
		Protocol:  "worktree-first",
		Challenge: "Creating a branch in the shared root workspace is a worktree-first protocol violation. Use the git_worktree tool instead. Run get_protocol('worktree-first') for the full rule.",
	}, nil
}

package builtins

import (
	"context"
	"encoding/json"
	"fmt"

	"cercano/source/server/internal/capabilities"
	"cercano/source/server/internal/gitflow"
)

type checkpointCap struct{}

// Checkpoint constructs the checkpoint capability. W-tier.
func Checkpoint() capabilities.Capability { return checkpointCap{} }

func (checkpointCap) Name() string            { return "checkpoint" }
func (checkpointCap) Tier() capabilities.Tier { return capabilities.TierW }
func (checkpointCap) Surfaces() capabilities.Surface {
	return capabilities.SurfaceAgent | capabilities.SurfaceMCP
}
func (checkpointCap) Description() string {
	return "Commit a solved unit of work on the current feature branch (never on trunk, never pushed). Args: {subject: string, body?: string, trunk?: string, cwd?: string}."
}
func (checkpointCap) Schema() capabilities.Schema {
	return capabilities.Schema(`{
		"type": "object",
		"required": ["subject"],
		"properties": {
			"subject": {"type": "string"},
			"body":    {"type": "string"},
			"trunk":   {"type": "string"},
			"cwd":     {"type": "string"}
		}
	}`)
}

type checkpointArgs struct {
	Subject string `json:"subject"`
	Body    string `json:"body"`
	Trunk   string `json:"trunk"`
	Cwd     string `json:"cwd"`
}

func (checkpointCap) Execute(ctx context.Context, call *capabilities.Call) (*capabilities.Result, error) {
	var a checkpointArgs
	if err := json.Unmarshal(call.Args, &a); err != nil {
		return nil, fmt.Errorf("checkpoint: parse args: %w", err)
	}
	dir := a.Cwd
	if dir == "" {
		dir = call.WorkDir
	}
	r, err := gitflow.Open(dir)
	if err != nil {
		return nil, fmt.Errorf("checkpoint: %w", err)
	}
	cfg, err := gitflow.Resolve(ctx, r, gitflow.Config{Trunk: a.Trunk})
	if err != nil {
		return nil, fmt.Errorf("checkpoint: %w", err)
	}
	sha, err := r.Checkpoint(ctx, a.Subject, a.Body, cfg.Trunk)
	if err != nil {
		return nil, err
	}
	return capabilities.NewTextResult(fmt.Sprintf("checkpoint committed %s on the current branch (not pushed)", sha[:min(12, len(sha))])), nil
}

package watchdog

import (
	"context"
	"encoding/json"
	"strings"
	"testing"
)

// argsJSON returns a JSON blob of the run_command Input shape with the given
// cmd argv. Kept local so tests don't reach into other packages.
func argsJSON(cmd ...string) json.RawMessage {
	b, err := json.Marshal(map[string]any{"cmd": cmd})
	if err != nil {
		panic(err)
	}
	return b
}

func TestWorktreeFirst_AppliesToDirectGitCheckoutB(t *testing.T) {
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("git", "checkout", "-b", "feat/foo"),
	}
	if !c.Applies(a) {
		t.Fatal("Applies should fire on `git checkout -b <name>`")
	}
}

func TestWorktreeFirst_AppliesToShellWrappedGitCheckoutB(t *testing.T) {
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("bash", "-lc", "git checkout -b feat/foo && echo ok"),
	}
	if !c.Applies(a) {
		t.Fatal("Applies should fire when the command is wrapped in `bash -lc`")
	}
}

func TestWorktreeFirst_AppliesToGitSwitchC(t *testing.T) {
	// `git switch -c <name>` is the modern equivalent of `git checkout -b`.
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("git", "switch", "-c", "feat/foo"),
	}
	if !c.Applies(a) {
		t.Fatal("Applies should fire on `git switch -c <name>`")
	}
}

func TestWorktreeFirst_DoesNotApplyToPlainCheckout(t *testing.T) {
	// Switching to an existing branch is legitimate and must NOT trip.
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("git", "checkout", "main"),
	}
	if c.Applies(a) {
		t.Fatal("Applies must not fire on `git checkout <existing-branch>`")
	}
}

func TestWorktreeFirst_DoesNotApplyToGitWorktreeAdd(t *testing.T) {
	// The whole point of the protocol is to steer agents TO worktree add;
	// blocking it would be self-defeating.
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("git", "worktree", "add", "-b", "feat/foo", "some/path"),
	}
	if c.Applies(a) {
		t.Fatal("Applies must not fire on `git worktree add -b <name>`")
	}
}

func TestWorktreeFirst_DoesNotApplyToNonRunCommandTool(t *testing.T) {
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "edit_file",
		ToolArgs: argsJSON("git", "checkout", "-b", "feat/foo"),
	}
	if c.Applies(a) {
		t.Fatal("Applies must be scoped to run_command; other tools are out of scope")
	}
}

func TestWorktreeFirst_DoesNotApplyToTurnEnd(t *testing.T) {
	c := WorktreeFirstCheck()
	a := Action{Kind: "turn_end", Text: "git checkout -b feat/foo"}
	if c.Applies(a) {
		t.Fatal("Applies must not fire on turn_end actions (checks the intent, not the prose)")
	}
}

func TestWorktreeFirst_EvaluateReturnsDeterministicViolation(t *testing.T) {
	c := WorktreeFirstCheck()
	// The check is deterministic — no LLM required, oneShot may be nil.
	v, err := c.Evaluate(context.Background(), Action{}, nil)
	if err != nil {
		t.Fatalf("Evaluate returned error: %v", err)
	}
	if !v.Violation {
		t.Fatal("Evaluate must return a violation whenever Applies fired")
	}
	if v.Protocol != "worktree-first" {
		t.Fatalf("Verdict.Protocol = %q, want worktree-first", v.Protocol)
	}
	if v.Challenge == "" {
		t.Fatal("Verdict.Challenge must be non-empty so the agent gets a specific nudge")
	}
	if !strings.Contains(v.Challenge, "git_worktree") {
		t.Fatalf("Challenge must name the git_worktree tool so the agent knows the escape hatch, got: %q", v.Challenge)
	}
}

