func writeFile(t *testing.T, r *Repo, name, content string) {
	t.Helper()
	if err := os.WriteFile(filepath.Join(r.Dir, name), []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestCheckpointCommitsOnFeatureBranch(t *testing.T) {
	r := newTestRepo(t)
	ctx := context.Background()
	if _, err := r.run(ctx, "checkout", "-b", "feature"); err != nil {
		t.Fatal(err)
	}
	writeFile(t, r, "a.txt", "hello")
	sha, err := r.Checkpoint(ctx, "feat: add a", "Adds the a file.", "main")
	if err != nil {
		t.Fatal(err)
	}
	if sha == "" {
		t.Fatal("expected a commit sha")
	}
	msg, _ := r.run(ctx, "log", "-1", "--pretty=%B")
	if !strings.Contains(msg, "feat: add a") || !strings.Contains(msg, "Adds the a file.") {
		t.Fatalf("message not assembled: %q", msg)
	}
}

func TestCheckpointRejectsClaudeAndTrunkAndEmpty(t *testing.T) {
	r := newTestRepo(t)
	ctx := context.Background()
	writeFile(t, r, "b.txt", "x")
	// On trunk → reject.
	if _, err := r.Checkpoint(ctx, "feat: b", "", "main"); err == nil {
		t.Fatal("expected error committing on trunk")
	}
	// Move to a branch.
	if _, err := r.run(ctx, "checkout", "-b", "feature"); err != nil {
		t.Fatal(err)
	}
	// "claude" anywhere → reject (case-insensitive).
	if _, err := r.Checkpoint(ctx, "feat: b (Claude wrote this)", "", "main"); err == nil {
		t.Fatal("expected error rejecting 'claude' in subject")
	}
	// Empty subject → reject.
	if _, err := r.Checkpoint(ctx, "", "body", "main"); err == nil {
		t.Fatal("expected error on empty subject")
	}
}

package gitflow

import (
	"context"
	"os"
	"os/exec"
	"testing"
)

// newTestRepo creates a temp git repo with one commit on branch "main".
func newTestRepo(t *testing.T) *Repo {
	t.Helper()
	dir := t.TempDir()
	run := func(args ...string) {
		cmd := exec.Command("git", args...)
		cmd.Dir = dir
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}
	run("init", "-b", "main")
	run("config", "user.email", "t@example.com")
	run("config", "user.name", "t")
	run("commit", "--allow-empty", "-m", "root")
	r, err := Open(dir)
	if err != nil {
		t.Fatal(err)
	}
	return r
}

func TestRepoBasics(t *testing.T) {
	r := newTestRepo(t)
	ctx := context.Background()

	clean, err := r.Clean(ctx)
	if err != nil || !clean {
		t.Fatalf("expected clean tree: clean=%v err=%v", clean, err)
	}
	br, err := r.CurrentBranch(ctx)
	if err != nil || br != "main" {
		t.Fatalf("branch: %q err=%v", br, err)
	}
	if _, err := r.RevParse(ctx, "HEAD"); err != nil {
		t.Fatalf("rev-parse HEAD: %v", err)
	}
	anc, err := r.IsAncestor(ctx, "HEAD", "HEAD")
	if err != nil || !anc {
		t.Fatalf("HEAD should be ancestor of itself: %v %v", anc, err)
	}
}

func TestCleanIgnoringUntracked_UntrackedFileDoesNotBlock(t *testing.T) {
	r := newTestRepo(t)
	ctx := context.Background()
	// Drop an untracked file in the repo.
	if err := os.WriteFile(r.Dir+"/newfile.txt", []byte("hi"), 0644); err != nil {
		t.Fatal(err)
	}
	if clean, err := r.Clean(ctx); err != nil || clean {
		t.Fatalf("vanilla Clean should now report NOT clean (untracked present): clean=%v err=%v", clean, err)
	}
	clean, err := r.CleanIgnoringUntracked(ctx)
	if err != nil {
		t.Fatal(err)
	}
	if !clean {
		t.Fatal("CleanIgnoringUntracked should treat pure-untracked state as clean")
	}
}

package watchdog

import (
	"context"
	"encoding/json"
	"strings"
	"testing"
)

// argsJSON returns a JSON blob of the run_command Input shape with the given
// cmd argv. Kept local so tests don't reach into other packages.
func argsJSON(cmd ...string) json.RawMessage {
	b, err := json.Marshal(map[string]any{"cmd": cmd})
	if err != nil {
		panic(err)
	}
	return b
}

func TestWorktreeFirst_AppliesToDirectGitCheckoutB(t *testing.T) {
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("git", "checkout", "-b", "feat/foo"),
	}
	if !c.Applies(a) {
		t.Fatal("Applies should fire on `git checkout -b <name>`")
	}
}

func TestWorktreeFirst_AppliesToShellWrappedGitCheckoutB(t *testing.T) {
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("bash", "-lc", "git checkout -b feat/foo && echo ok"),
	}
	if !c.Applies(a) {
		t.Fatal("Applies should fire when the command is wrapped in `bash -lc`")
	}
}

func TestWorktreeFirst_AppliesToGitSwitchC(t *testing.T) {
	// `git switch -c <name>` is the modern equivalent of `git checkout -b`.
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("git", "switch", "-c", "feat/foo"),
	}
	if !c.Applies(a) {
		t.Fatal("Applies should fire on `git switch -c <name>`")
	}
}

func TestWorktreeFirst_DoesNotApplyToPlainCheckout(t *testing.T) {
	// Switching to an existing branch is legitimate and must NOT trip.
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("git", "checkout", "main"),
	}
	if c.Applies(a) {
		t.Fatal("Applies must not fire on `git checkout <existing-branch>`")
	}
}

func TestWorktreeFirst_DoesNotApplyToGitWorktreeAdd(t *testing.T) {
	// The whole point of the protocol is to steer agents TO worktree add;
	// blocking it would be self-defeating.
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "run_command",
		ToolArgs: argsJSON("git", "worktree", "add", "-b", "feat/foo", "some/path"),
	}
	if c.Applies(a) {
		t.Fatal("Applies must not fire on `git worktree add -b <name>`")
	}
}

func TestWorktreeFirst_DoesNotApplyToNonRunCommandTool(t *testing.T) {
	c := WorktreeFirstCheck()
	a := Action{
		Kind:     "tool_call",
		ToolName: "edit_file",
		ToolArgs: argsJSON("git", "checkout", "-b", "feat/foo"),
	}
	if c.Applies(a) {
		t.Fatal("Applies must be scoped to run_command; other tools are out of scope")
	}
}

func TestWorktreeFirst_DoesNotApplyToTurnEnd(t *testing.T) {
	c := WorktreeFirstCheck()
	a := Action{Kind: "turn_end", Text: "git checkout -b feat/foo"}
	if c.Applies(a) {
		t.Fatal("Applies must not fire on turn_end actions (checks the intent, not the prose)")
	}
}

func TestWorktreeFirst_EvaluateReturnsDeterministicViolation(t *testing.T) {
	c := WorktreeFirstCheck()
	// The check is deterministic — no LLM required, oneShot may be nil.
	v, err := c.Evaluate(context.Background(), Action{}, nil)
	if err != nil {
		t.Fatalf("Evaluate returned error: %v", err)
	}
	if !v.Violation {
		t.Fatal("Evaluate must return a violation whenever Applies fired")
	}
	if v.Protocol != "worktree-first" {
		t.Fatalf("Verdict.Protocol = %q, want worktree-first", v.Protocol)
	}
	if v.Challenge == "" {
		t.Fatal("Verdict.Challenge must be non-empty so the agent gets a specific nudge")
	}
	if !strings.Contains(v.Challenge, "git_worktree") {
		t.Fatalf("Challenge must name the git_worktree tool so the agent knows the escape hatch, got: %q", v.Challenge)
	}
}

