	res, err := cap.Execute(context.Background(), &capabilities.Call{Args: args, WorkDir: dir})
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(res.Text, "checkpoint committed") {
		t.Fatalf("unexpected result: %q", res.Text)
