// Package skills is the single source of truth for Cercano's tool Agent
// Skills. The canonical SKILL.md files live in the embedded catalog/
// directory; the on-disk .agents/skills and .claude/skills trees at the repo
// root are GENERATED from it via WriteTrees (`cercano skills sync`). Do not
// edit those trees by hand — edit catalog/ and regenerate, or the drift-gate
// test (TestGeneratedTreesMatchRepo) will fail.
//
// Flavors: the .agents tree receives the canonical content verbatim. The
// .claude tree receives the canonical content plus a fixed "display the
// result" section inserted before the first H2 heading — Claude Code
// sessions don't always surface MCP tool results to the user, so the skill
// must instruct the model to echo them.
package skills

import (
	"embed"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

//go:embed catalog
var catalogFS embed.FS

// Skill is one entry in the canonical catalog.
type Skill struct {
	Name        string // directory name, e.g. "cercano-research"
	Description string // frontmatter description line (for RPC listing)
	Content     string // canonical SKILL.md content (the .agents flavor)
}

// displayResultSection is the .claude-flavor addition. Inserted before the
// first "## " heading of the canonical content.
const displayResultSection = "## Important: Display the result\n\n" +
	"MCP tool results may not be visible to the user in the terminal. " +
	"After calling the tool, you MUST output the full tool result text " +
	"verbatim in your response so the user can see it.\n\n"

// Catalog returns all skills in the embedded catalog, sorted by name.
func Catalog() ([]Skill, error) {
	entries, err := fs.ReadDir(catalogFS, "catalog")
	if err != nil {
		return nil, fmt.Errorf("skills: read embedded catalog: %w", err)
	}
	out := make([]Skill, 0, len(entries))
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		raw, err := fs.ReadFile(catalogFS, "catalog/"+e.Name()+"/SKILL.md")
		if err != nil {
			return nil, fmt.Errorf("skills: %s has no SKILL.md: %w", e.Name(), err)
		}
		content := string(raw)
		desc, err := frontmatterDescription(content)
		if err != nil {
			return nil, fmt.Errorf("skills: %s: %w", e.Name(), err)
		}
		out = append(out, Skill{Name: e.Name(), Description: desc, Content: content})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// frontmatterDescription extracts the description value from the first
// frontmatter block. Fails loudly on malformed frontmatter: a skill without
// a description would render an empty RPC listing entry, which is silent
// breakage of exactly the kind this package exists to prevent.
func frontmatterDescription(content string) (string, error) {
	lines := strings.Split(content, "\n")
	if len(lines) == 0 || strings.TrimSpace(lines[0]) != "---" {
		return "", fmt.Errorf("missing frontmatter open")
	}
	for _, ln := range lines[1:] {
		if strings.TrimSpace(ln) == "---" {
			return "", fmt.Errorf("frontmatter has no description key")
		}
		if v, ok := strings.CutPrefix(ln, "description:"); ok {
			return strings.TrimSpace(v), nil
		}
	}
	return "", fmt.Errorf("frontmatter never closed")
}

// RenderClaude returns the .claude flavor of canonical content: the
// display-result section is inserted immediately before the first line that
// starts a "## " heading. Content with no H2 headings gets the section
// appended at the end.
func RenderClaude(content string) string {
	lines := strings.Split(content, "\n")
	for i, ln := range lines {
		if strings.HasPrefix(ln, "## ") {
			head := strings.Join(lines[:i], "\n")
			tail := strings.Join(lines[i:], "\n")
			return head + "\n" + displayResultSection + tail
		}
	}
	return strings.TrimRight(content, "\n") + "\n\n" + strings.TrimRight(displayResultSection, "\n") + "\n"
}

// trees maps each on-disk skill tree to its renderer.
var trees = []struct {
	dir    string
	render func(string) string
}{
	{".agents/skills", func(c string) string { return c }},
	{".claude/skills", RenderClaude},
}

// WriteTrees renders every catalog skill into both discovery trees under
// rootDir, returning the paths written.
func WriteTrees(rootDir string) ([]string, error) {
	cat, err := Catalog()
	if err != nil {
		return nil, err
	}
	var written []string
	for _, sk := range cat {
		for _, t := range trees {
			dir := filepath.Join(rootDir, t.dir, sk.Name)
			if err := os.MkdirAll(dir, 0o755); err != nil {
				return written, fmt.Errorf("skills: mkdir %s: %w", dir, err)
			}
			path := filepath.Join(dir, "SKILL.md")
			if err := os.WriteFile(path, []byte(t.render(sk.Content)), 0o644); err != nil {
				return written, fmt.Errorf("skills: write %s: %w", path, err)
			}
			written = append(written, path)
		}
	}
	return written, nil
}

package server

import (
	"context"
	"fmt"

	"cercano/source/server/internal/skills"
	"cercano/source/server/pkg/proto"
)

// ListSkills implements proto.AgentServer — returns the catalog of available
// Agent Skills. The catalog is the embedded single source in internal/skills;
// the on-disk .agents/skills and .claude/skills trees are generated from the
// same source, so RPC listing and file discovery can't drift apart.
func (s *Server) ListSkills(ctx context.Context, req *proto.ListSkillsRequest) (*proto.ListSkillsResponse, error) {
	cat, err := skills.Catalog()
	if err != nil {
		return nil, err
	}
	protoSkills := make([]*proto.SkillInfo, len(cat))
	for i, sk := range cat {
		protoSkills[i] = &proto.SkillInfo{
			Name:        sk.Name,
			Description: sk.Description,
		}
	}
	return &proto.ListSkillsResponse{Skills: protoSkills}, nil
}

// GetSkill implements proto.AgentServer — returns the full canonical SKILL.md
// content for a specific skill.
func (s *Server) GetSkill(ctx context.Context, req *proto.GetSkillRequest) (*proto.GetSkillResponse, error) {
	cat, err := skills.Catalog()
	if err != nil {
		return nil, err
	}
	for _, sk := range cat {
		if sk.Name == req.Name {
			return &proto.GetSkillResponse{
				Name:    sk.Name,
				Content: sk.Content,
			}, nil
		}
	}
	return nil, fmt.Errorf("skill %q not found", req.Name)
}

// Command cercano-cli is the standalone terminal client for Cercano.
//
// It is a thin gRPC client: it connects to a running cercano agent server on
// localhost:<port>, or auto-launches one (as `cercano agent`) if none is
// listening. The agent server is a singleton — multiple clients (this CLI, the
// VS Code extension, etc.) share the same server and conversation store.
package main

import (
	"context"
	"flag"
	"fmt"
	"os"
	"strings"

	tea "charm.land/bubbletea/v2"

	cliui "cercano/source/clients/cli/internal/ui"
	"cercano/source/clients/cli/internal/wizard"
	"cercano/source/server/pkg/agentclient"
	"cercano/source/server/pkg/config"
	"cercano/source/server/pkg/update"
)

// version is set at build time via -ldflags "-X main.version=...".
// Falls back to "dev" for local builds.
var version = "dev"

func init() {
	// Normalize: strip leading "v" so the print format "v%s" doesn't double up.
	version = strings.TrimPrefix(version, "v")
}

func main() {
	resumeShort := flag.Bool("r", false, "Open the conversation history picker on launch (alias for --resume)")
	resumeLong := flag.Bool("resume", false, "Open the conversation history picker on launch")
	setupShort := flag.Bool("s", false, "Open the setup wizard on launch (alias for --setup)")
	setupLong := flag.Bool("setup", false, "Open the setup wizard on launch")
	mdtest := flag.Bool("mdtest", false, "Launch the TUI with a markdown doc pre-loaded for render testing (optional file path as a positional arg; built-in sample if omitted)")
	showVersion := flag.Bool("version", false, "Print version and exit")
	flag.Parse()

	if *showVersion {
		fmt.Printf("cercano-cli v%s\n", version)
		if info := update.CheckForUpdate(version); info != nil {
			if info.UpdateAvailable {
				fmt.Printf("\nA newer version is available: v%s\n", info.LatestVersion)
				fmt.Printf("  Upgrade: %s\n", info.UpgradeCommand())
				fmt.Printf("  Release: %s\n", info.ReleaseURL)
			} else {
				fmt.Println("(up to date)")
			}
		}
		return
	}

	// Config is shared with the server (pkg/config); the CLI needs the port to
	// dial the agent.
	cfg, err := config.Load(config.DefaultPath())
	if err != nil {
		fmt.Fprintf(os.Stderr, "[WARN] Failed to load config: %v (using defaults)\n", err)
		cfg = config.Defaults()
	}

	openHistory := *resumeShort || *resumeLong
	// The wizard opens on explicit request, on first run (no config file
	// yet), or when a previous run was left unfinished (resume).
	openWizard := *setupShort || *setupLong
	if !openWizard {
		if _, statErr := os.Stat(config.DefaultPath()); os.IsNotExist(statErr) {
			openWizard = true
		}
	}
	if !openWizard {
		_, openWizard = wizard.Load()
	}
	seedDoc := ""
	if *mdtest {
		// Render-testing mode: launch the TUI with a markdown doc pre-loaded.
		// No model round-trip — the doc renders through the normal viewport path.
		seedDoc = loadMdTestDoc(flag.Arg(0))
	}
	runCLI(cfg, openHistory, openWizard, seedDoc)
}

// runCLI launches the cercano TUI. Connects to a running agent on
// localhost:<cfg.Port>, or auto-launches one (as `cercano agent`) on miss.
// openHistoryOnStart opens the /history picker immediately after first paint
// (used by the -r / --resume flag).
func runCLI(cfg config.Config, openHistoryOnStart, openWizardOnStart bool, seedDoc string) {
	addr := "localhost:" + cfg.Port
	fmt.Fprintln(os.Stderr, "cercano: connecting to", addr+"…")
	ag, err := agentclient.Dial(context.Background(), addr)
	if err != nil {
		fmt.Fprintln(os.Stderr, "cercano:", err)
		os.Exit(1)
	}
	defer ag.Close()
	if ag.AutoLaunched {
		fmt.Fprintln(os.Stderr, "cercano: auto-launched agent server (log:", ag.ServerLog+")")
	}

	m := cliui.New(ag, openHistoryOnStart)
	if openWizardOnStart {
		m = m.OpenWizardOnStart()
	}
	if seedDoc != "" {
		m = m.SeedAssistantMarkdown(seedDoc)
	}
	p := tea.NewProgram(m)
	if _, err := p.Run(); err != nil {
		fmt.Fprintln(os.Stderr, "cercano:", err)
		os.Exit(1)
	}
}

