// Package protocols is the single source for Cercano's workflow protocols.
// One protocol document feeds three outputs: the always-on steering block
// (Trigger lines), the get_protocol capability (Body), and generated SKILL.md
// files for host discovery. Ported from the hardwAIr_hckr "Dave" core skills
// and the generic khalkulo/workflow decision protocol.
package protocols

import "sort"

// Domain separates generic protocols from domain-specific ones so the default
// steering set can exclude hardware protocols.
type Domain string

const (
	DomainCore     Domain = "core"
	DomainHardware Domain = "hardware"
)

// Protocol is one workflow discipline.
type Protocol struct {
	Name        string // kebab-case id, e.g. "design-decisions"
	Description string // one-line, for skill discovery
	Domain      Domain
	Trigger     string // one-line always-on rule (feeds the steering block)
	Body        string // the full protocol markdown (pulled on demand)
}

// Builtins returns the built-in protocol catalog, sorted by name.
func Builtins() []Protocol {
	out := append([]Protocol(nil), builtinProtocols...)
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out
}

// Get returns a protocol by name.
func Get(name string) (Protocol, bool) {
	for _, p := range builtinProtocols {
		if p.Name == name {
			return p, true
		}
	}
	return Protocol{}, false
}

// ForDomain returns protocols in the given domain, sorted by name.
func ForDomain(d Domain) []Protocol {
	var out []Protocol
	for _, p := range Builtins() {
		if p.Domain == d {
			out = append(out, p)
		}
	}
	return out
}

package server

import (
	"context"
	"fmt"

	"cercano/source/server/internal/skills"
	"cercano/source/server/pkg/proto"
)

// ListSkills implements proto.AgentServer — returns the catalog of available
// Agent Skills. The catalog is the embedded single source in internal/skills;
// the on-disk .agents/skills and .claude/skills trees are generated from the
// same source, so RPC listing and file discovery can't drift apart.
func (s *Server) ListSkills(ctx context.Context, req *proto.ListSkillsRequest) (*proto.ListSkillsResponse, error) {
	cat, err := skills.Catalog()
	if err != nil {
		return nil, err
	}
	protoSkills := make([]*proto.SkillInfo, len(cat))
	for i, sk := range cat {
		protoSkills[i] = &proto.SkillInfo{
			Name:        sk.Name,
			Description: sk.Description,
		}
	}
	return &proto.ListSkillsResponse{Skills: protoSkills}, nil
}

// GetSkill implements proto.AgentServer — returns the full canonical SKILL.md
// content for a specific skill.
func (s *Server) GetSkill(ctx context.Context, req *proto.GetSkillRequest) (*proto.GetSkillResponse, error) {
	cat, err := skills.Catalog()
	if err != nil {
		return nil, err
	}
	for _, sk := range cat {
		if sk.Name == req.Name {
			return &proto.GetSkillResponse{
				Name:    sk.Name,
				Content: sk.Content,
			}, nil
		}
	}
	return nil, fmt.Errorf("skill %q not found", req.Name)
}

// Package skills is the single source of truth for Cercano's tool Agent
// Skills. The canonical SKILL.md files live in the embedded catalog/
// directory; the on-disk .agents/skills and .claude/skills trees at the repo
// root are GENERATED from it via WriteTrees (`cercano skills sync`). Do not
// edit those trees by hand — edit catalog/ and regenerate, or the drift-gate
// test (TestGeneratedTreesMatchRepo) will fail.
//
// Flavors: the .agents tree receives the canonical content verbatim. The
// .claude tree receives the canonical content plus a fixed "display the
// result" section inserted before the first H2 heading — Claude Code
// sessions don't always surface MCP tool results to the user, so the skill
// must instruct the model to echo them.
package skills

import (
	"embed"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

//go:embed catalog
var catalogFS embed.FS

// Skill is one entry in the canonical catalog.
type Skill struct {
	Name        string // directory name, e.g. "cercano-research"
	Description string // frontmatter description line (for RPC listing)
	Content     string // canonical SKILL.md content (the .agents flavor)
}

// displayResultSection is the .claude-flavor addition. Inserted before the
// first "## " heading of the canonical content.
const displayResultSection = "## Important: Display the result\n\n" +
	"MCP tool results may not be visible to the user in the terminal. " +
	"After calling the tool, you MUST output the full tool result text " +
	"verbatim in your response so the user can see it.\n\n"

// Catalog returns all skills in the embedded catalog, sorted by name.
func Catalog() ([]Skill, error) {
	entries, err := fs.ReadDir(catalogFS, "catalog")
	if err != nil {
		return nil, fmt.Errorf("skills: read embedded catalog: %w", err)
	}
	out := make([]Skill, 0, len(entries))
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		raw, err := fs.ReadFile(catalogFS, "catalog/"+e.Name()+"/SKILL.md")
		if err != nil {
			return nil, fmt.Errorf("skills: %s has no SKILL.md: %w", e.Name(), err)
		}
		content := string(raw)
		desc, err := frontmatterDescription(content)
		if err != nil {
			return nil, fmt.Errorf("skills: %s: %w", e.Name(), err)
		}
		out = append(out, Skill{Name: e.Name(), Description: desc, Content: content})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Name < out[j].Name })
	return out, nil
}

// frontmatterDescription extracts the description value from the first
// frontmatter block. Fails loudly on malformed frontmatter: a skill without
// a description would render an empty RPC listing entry, which is silent
// breakage of exactly the kind this package exists to prevent.
func frontmatterDescription(content string) (string, error) {
	lines := strings.Split(content, "\n")
	if len(lines) == 0 || strings.TrimSpace(lines[0]) != "---" {
		return "", fmt.Errorf("missing frontmatter open")
	}
	for _, ln := range lines[1:] {
		if strings.TrimSpace(ln) == "---" {
			return "", fmt.Errorf("frontmatter has no description key")
		}
		if v, ok := strings.CutPrefix(ln, "description:"); ok {
			return strings.TrimSpace(v), nil
		}
	}
	return "", fmt.Errorf("frontmatter never closed")
}

// RenderClaude returns the .claude flavor of canonical content: the
// display-result section is inserted immediately before the first line that
// starts a "## " heading. Content with no H2 headings gets the section
// appended at the end.
func RenderClaude(content string) string {
	lines := strings.Split(content, "\n")
	for i, ln := range lines {
		if strings.HasPrefix(ln, "## ") {
			head := strings.Join(lines[:i], "\n")
			tail := strings.Join(lines[i:], "\n")
			return head + "\n" + displayResultSection + tail
		}
	}
	return strings.TrimRight(content, "\n") + "\n\n" + strings.TrimRight(displayResultSection, "\n") + "\n"
}

// trees maps each on-disk skill tree to its renderer.
var trees = []struct {
	dir    string
	render func(string) string
}{
	{".agents/skills", func(c string) string { return c }},
	{".claude/skills", RenderClaude},
}

// WriteTrees renders every catalog skill into both discovery trees under
// rootDir, returning the paths written.
func WriteTrees(rootDir string) ([]string, error) {
	cat, err := Catalog()
	if err != nil {
		return nil, err
	}
	var written []string
	for _, sk := range cat {
		for _, t := range trees {
			dir := filepath.Join(rootDir, t.dir, sk.Name)
			if err := os.MkdirAll(dir, 0o755); err != nil {
				return written, fmt.Errorf("skills: mkdir %s: %w", dir, err)
			}
			path := filepath.Join(dir, "SKILL.md")
			if err := os.WriteFile(path, []byte(t.render(sk.Content)), 0o644); err != nil {
				return written, fmt.Errorf("skills: write %s: %w", path, err)
			}
			written = append(written, path)
		}
	}
	return written, nil
}

package watchdog

import (
	"context"
	"fmt"
	"strings"

	"cercano/source/server/internal/llm"
)

type debugLoopCheck struct{}

// DebugLoopCheck flags edits made to fix a bug/test failure with no evidence of
// the systematic-debugging loop in the recent transcript.
func DebugLoopCheck() Check { return debugLoopCheck{} }

func (debugLoopCheck) Name() string { return "debug-loop" }

var editTools = map[string]bool{"edit_file": true, "write_file": true, "rm_file": true, "git_reset_hard": true}

func (debugLoopCheck) Applies(a Action) bool {
	return a.Kind == "tool_call" && editTools[canonical(a.ToolName)]
}

func (debugLoopCheck) Evaluate(ctx context.Context, a Action, oneShot OneShotFunc) (Verdict, error) {
	if oneShot == nil {
		return Verdict{Protocol: "debug-loop"}, nil // no model → fail open
	}
	prompt := buildDebugLoopPrompt(a)
	out, err := oneShot(ctx, prompt)
	if err != nil {
		return Verdict{}, err
	}
	return parseVerdict("debug-loop", out), nil
}

func buildDebugLoopPrompt(a Action) string {
	var b strings.Builder
	b.WriteString("You are a supervisor enforcing the systematic-debugging protocol.\n")
	b.WriteString("The agent is about to run a code-mutating tool. Judge ONLY whether it is fixing a bug or test failure WITHOUT evidence in the recent transcript of the debug loop: reducing to the smallest failing case, observing actual data/output, and confirming the root cause with a probe. Refactors, new features, and edits with clear prior evidence are NOT violations.\n\n")
	fmt.Fprintf(&b, "Proposed action: %s %s\n\n", a.ToolName, string(a.ToolArgs))
	b.WriteString("Recent transcript:\n")
	b.WriteString(transcriptTail(a.Transcript, 12))
	b.WriteString("\n\nRespond EXACTLY:\nVIOLATION: yes|no\nCHALLENGE: <one line, only if yes>\n")
	return b.String()
}

// transcriptTail renders the last n messages as plain text for the prompt.
func transcriptTail(msgs []llm.Message, n int) string {
	if len(msgs) > n {
		msgs = msgs[len(msgs)-n:]
	}
	var b strings.Builder
	for _, m := range msgs {
		for _, blk := range m.Blocks {
			if blk.Type == llm.BlockText && strings.TrimSpace(blk.Text) != "" {
				fmt.Fprintf(&b, "[%s] %s\n", m.Role, strings.TrimSpace(blk.Text))
			}
		}
	}
	return b.String()
}

package watchdog

import (
	"context"
	"crypto/sha256"
	"fmt"
	"log"
	"sync"
	"time"
)

// Mode controls how the Watchdog responds to a first-time violation.
type Mode string

const (
	ModeChallenge Mode = "challenge-and-justify"
	ModeStrict    Mode = "strict"
)

// Decision is the result returned by Gate.
type Decision struct {
	Action    string // "allow" | "challenge" | "block" | "escalate"
	Protocol  string
	Challenge string
	// Revise carries the violated check's corrective instruction (Verdict.Revise).
	Revise string
}

// Config tunes Watchdog behaviour.
// EscalateAfter: number of times the same key must be seen before escalation.
// Zero means default (2).
// CheckTimeout bounds each Gate call's check evaluation. Zero means default
// (15s). Supervision must never wedge the supervised: a turn-end gate runs
// after the reply has already streamed, so an unbounded check against a sick
// model lane holds the stream open and the client queues everything.
type Config struct {
	Mode          Mode
	EscalateAfter int
	CheckTimeout  time.Duration
}

// convState holds per-conversation state.
type convState struct {
	justified      map[string]bool
	counts         map[string]int
	lastChallenged string // key most recently challenged or escalated for this conversation
}

// Watchdog runs a set of Checks against agent Actions and enforces a
// per-conversation challenge/block/escalate policy.
type Watchdog struct {
	cfg           Config
	checks        []Check
	oneShot       OneShotFunc
	escalateAfter int
	checkTimeout  time.Duration

	mu    sync.Mutex
	convs map[string]*convState

	echo func(thread, text string) // optional; nil means silent
}

// SetEcho registers a callback that is called on watchdog interventions and
// justify overrides. thread is "watchdog" or "main". Synchronized with w.mu,
// so it may be called on a live Watchdog; note the callback is global to the
// Watchdog, not per-conversation — under concurrent conversations, echo lines
// from all of them reach the same callback.
func (w *Watchdog) SetEcho(fn func(thread, text string)) {
	w.mu.Lock()
	w.echo = fn
	w.mu.Unlock()
}

// emitEcho calls the echo callback if one is registered. It briefly acquires
// w.mu to snapshot the callback, so callers must NOT hold w.mu (sync.Mutex is
// not reentrant). The callback itself runs outside the lock, so it can never
// deadlock the watchdog.
func (w *Watchdog) emitEcho(thread, text string) {
	w.mu.Lock()
	fn := w.echo
	w.mu.Unlock()
	if fn != nil {
		fn(thread, text)
	}
}

// New creates a ready Watchdog.
func New(cfg Config, checks []Check, oneShot OneShotFunc) *Watchdog {
	ea := cfg.EscalateAfter
	if ea <= 0 {
		ea = 2
	}
	ct := cfg.CheckTimeout
	if ct <= 0 {
		ct = 15 * time.Second
	}
	return &Watchdog{
		cfg:           cfg,
		checks:        checks,
		oneShot:       oneShot,
		escalateAfter: ea,
		checkTimeout:  ct,
		convs:         make(map[string]*convState),
	}
}

// keyFor returns the action-identity key for dedup / justify tracking.
// Format: protocol + "|" + toolName + "|" + first-12-hex-chars-of-sha256(identity).
// For turn_end actions the identity is the reply text; for tool_call it is ToolArgs.
func keyFor(protocol string, a Action) string {
	identity := a.ToolArgs
	if a.Kind == "turn_end" {
		identity = []byte(a.Text)
	}
	sum := sha256.Sum256(identity)
	return fmt.Sprintf("%s|%s|%x", protocol, a.ToolName, sum[:6]) // 6 bytes = 12 hex chars
}

// getOrCreate returns the convState for the given conversation, creating it lazily.
// Caller must hold w.mu.
func (w *Watchdog) getOrCreate(conversationID string) *convState {
	cs, ok := w.convs[conversationID]
	if !ok {
		cs = &convState{
			justified: make(map[string]bool),
			counts:    make(map[string]int),
		}
		w.convs[conversationID] = cs
	}
	return cs
}

// Gate evaluates all checks against action a and returns a Decision.
func (w *Watchdog) Gate(ctx context.Context, conversationID string, a Action) Decision {
	// Bound the whole evaluation: a supervision verdict that takes longer than
	// checkTimeout is useless, and on the turn_end path an unbounded check
	// holds the client's stream open behind it. Deadline expiry rides the
	// existing fail-open error path below.
	ctx, cancel := context.WithTimeout(ctx, w.checkTimeout)
	defer cancel()
	// Run checks; fail-open on error.
	var violation *Verdict
	for _, ch := range w.checks {
		if !ch.Applies(a) {
			continue
		}
		v, err := ch.Evaluate(ctx, a, w.oneShot)
		if err != nil {
			log.Printf("watchdog: check %q error (fail-open): %v", ch.Name(), err)
			continue
		}
		if v.Violation {
			vCopy := v
			violation = &vCopy
			break
		}
	}

	if violation == nil {
		return Decision{Action: "allow"}
	}

	key := keyFor(violation.Protocol, a)

	w.mu.Lock()
	cs := w.getOrCreate(conversationID)
	if cs.justified[key] {
		w.mu.Unlock()
		return Decision{Action: "allow", Protocol: violation.Protocol}
	}
	cs.counts[key]++
	count := cs.counts[key]
	isStrict := w.cfg.Mode == ModeStrict
	escalate := count >= w.escalateAfter
	if escalate || !isStrict {
		cs.lastChallenged = key
	}
	w.mu.Unlock()

	if escalate {
		w.emitEcho("watchdog", fmt.Sprintf("[escalate] %s: %s", violation.Protocol, violation.Challenge))
		return Decision{Action: "escalate", Protocol: violation.Protocol, Challenge: violation.Challenge, Revise: violation.Revise}
	}
	if isStrict {
		w.emitEcho("watchdog", fmt.Sprintf("[block] %s: %s", violation.Protocol, violation.Challenge))
		return Decision{Action: "block", Protocol: violation.Protocol, Challenge: violation.Challenge, Revise: violation.Revise}
	}
	w.emitEcho("watchdog", fmt.Sprintf("[challenge] %s: %s", violation.Protocol, violation.Challenge))
	return Decision{Action: "challenge", Protocol: violation.Protocol, Challenge: violation.Challenge, Revise: violation.Revise}
}

// recordJustify marks key as justified for the given conversation so Gate
// will allow future matching actions without re-challenging.
func (w *Watchdog) recordJustify(conversationID, key string) {
	w.mu.Lock()
	defer w.mu.Unlock()
	cs := w.getOrCreate(conversationID)
	cs.justified[key] = true
}

// lastChallengedKey returns the key most recently challenged or escalated for
// the given conversation, or "" if none.
func (w *Watchdog) lastChallengedKey(conversationID string) string {
	w.mu.Lock()
	defer w.mu.Unlock()
	cs, ok := w.convs[conversationID]
	if !ok {
		return ""
	}
	return cs.lastChallenged
