package watchdog

import (
	"context"
	"fmt"
	"strings"

	"cercano/source/server/internal/llm"
)

type commitCheckpointCheck struct{}

// CommitCheckpointCheck nudges the agent to commit a completed unit of work
// before starting a different one. The trigger is a semantic work boundary, not
// a count.
func CommitCheckpointCheck() Check { return commitCheckpointCheck{} }

func (commitCheckpointCheck) Name() string { return "commit-checkpoint" }

// workEditTools are the code-mutating calls whose accumulation is "uncommitted
// work". git_reset_hard is intentionally excluded (it is not authored work).
var workEditTools = map[string]bool{"edit_file": true, "write_file": true, "rm_file": true}

// commitTools mark a commit boundary. Both the semantic checkpoint capability
// and the lower-level git_commit reset uncommitted work.
var commitTools = map[string]bool{"checkpoint": true, "git_commit": true}

func (commitCheckpointCheck) Applies(a Action) bool {
	if a.Kind != "tool_call" || !workEditTools[canonical(a.ToolName)] {
		return false
	}
	return uncommittedEditCount(a.Transcript) > 0
}

// uncommittedEditCount counts work-edit tool calls in the transcript that occur
// after the most recent commit tool call.
func uncommittedEditCount(msgs []llm.Message) int {
	n := 0
	for _, m := range msgs {
		for _, b := range m.Blocks {
			if b.Type != llm.BlockToolUse {
				continue
			}
			if commitTools[canonical(b.ToolName)] {
				n = 0 // a commit clears the running count
			} else if workEditTools[canonical(b.ToolName)] {
				n++
			}
		}
	}
	return n
}

func (commitCheckpointCheck) Evaluate(ctx context.Context, a Action, oneShot OneShotFunc) (Verdict, error) {
	if oneShot == nil {
		return Verdict{Protocol: "commit-checkpoint"}, nil // fail open
	}
	out, err := oneShot(ctx, buildCommitCheckpointPrompt(a))
	if err != nil {
		return Verdict{}, err
	}
	return parseVerdict("commit-checkpoint", out), nil
}

func buildCommitCheckpointPrompt(a Action) string {
	var b strings.Builder
	b.WriteString("You are a supervisor enforcing commit discipline.\n")
	b.WriteString("The agent has made edits since the last commit and is about to make another. Judge ONLY whether the NEW edit begins a DIFFERENT unit of work than the uncommitted edits — such that the prior work now forms a complete, committable change that should be committed first. A continuation of the same change is NOT a violation. A passing test or build in the transcript is evidence a unit may have completed, but is not by itself a reason to commit (it can be mid-work).\n\n")
	b.WriteString("Uncommitted edits so far (most recent last):\n")
	for _, line := range uncommittedEditSummary(a.Transcript) {
		fmt.Fprintf(&b, "  - %s\n", line)
	}
	fmt.Fprintf(&b, "\nNew edit about to run: %s %s\n\n", a.ToolName, string(a.ToolArgs))
	b.WriteString("Respond EXACTLY:\nVIOLATION: yes|no\nCHALLENGE: <one line, only if yes>\n")
	return b.String()
}

// uncommittedEditSummary lists the work-edits since the last commit as
// "toolname args" lines (args truncated).
func uncommittedEditSummary(msgs []llm.Message) []string {
	var out []string
	for _, m := range msgs {
		for _, b := range m.Blocks {
			if b.Type != llm.BlockToolUse {
				continue
			}
			if commitTools[canonical(b.ToolName)] {
				out = nil
			} else if workEditTools[canonical(b.ToolName)] {
				arg := string(b.ToolInput)
				if len(arg) > 120 {
					arg = arg[:120]
				}
				out = append(out, b.ToolName+" "+arg)
			}
		}
	}
	return out
}

// Package watchdog — worktreefirst.go: enforces the worktree-first protocol
// by blocking `git checkout -b` and `git switch -c` when they'd land in the
// shared root workspace. Agents are steered to the git_worktree tool instead.
//
// The check is deterministic — no LLM required. Applies fires whenever the
// pattern is present in a run_command tool call; Evaluate returns a fixed
// violation with a challenge that names the escape hatch (the git_worktree
// tool) and points at the protocol body for the rationale.
package watchdog

import (
	"context"
	"encoding/json"
	"regexp"
	"strings"
)

type worktreeFirstCheck struct{}

// WorktreeFirstCheck refuses raw branch-creation shell commands so agents
// use the git_worktree tool instead.
func WorktreeFirstCheck() Check { return worktreeFirstCheck{} }

func (worktreeFirstCheck) Name() string { return "worktree-first" }

// runCommandToolName is the canonical name of the shell-execution
// capability inside Cercano's tool registry. Kept as a constant so the
// Applies filter stays legible.
const runCommandToolName = "run_command"

// branchCreatePattern matches raw shell forms that create a new branch:
//   - git checkout -b <name>
//   - git checkout -B <name>
//   - git switch -c <name>
//   - git switch -C <name>
//
// Whitespace between tokens is flexible; the pattern anchors on word
// boundaries so `-branch` (a partial match) doesn't trip it.
var branchCreatePattern = regexp.MustCompile(`\bgit\s+(?:checkout\s+-B?|switch\s+-C?)\b`)

// runCommandInput mirrors the Input struct of the run_command capability so
// we can decode ToolArgs without importing the builtin package (which would
// cycle with the server package that owns Gate).
type runCommandInput struct {
	Cmd []string `json:"cmd"`
	Cwd string   `json:"cwd"`
}

func (worktreeFirstCheck) Applies(a Action) bool {
	if a.Kind != "tool_call" || canonical(a.ToolName) != runCommandToolName {
		return false
	}
	var in runCommandInput
	if err := json.Unmarshal(a.ToolArgs, &in); err != nil {
		return false
	}
	// Flatten into one effective command line so both direct
	// invocations (`git checkout -b …`) and shell wrappers
	// (`bash -lc "git checkout -b …"`) both match.
	line := strings.Join(in.Cmd, " ")
	return branchCreatePattern.MatchString(line)
}

// Evaluate returns a fixed violation whenever Applies matched. The challenge
// text names the usual escape hatch (the git_worktree tool) and reminds the
// agent that tiny current-branch edits should be explicit rather than swept up.
func (worktreeFirstCheck) Evaluate(_ context.Context, _ Action, _ OneShotFunc) (Verdict, error) {
	return Verdict{
		Violation: true,
		Protocol:  "worktree-first",
		Challenge: "Do not create a branch in the shared root workspace by default. Use git_worktree for substantial work. For a tiny current-branch edit, ask if unsure and use checkpoint with explicit paths instead. Run get_protocol('worktree-first') for the full rule.",
	}, nil
}

package watchdog

import "sync"

// Tool-name canonicalization. The standalone agent registers several
// capabilities under display aliases (Edit for edit_file, Bash for
// run_command, Write for write_file, …), and both the gated action and the
// transcript blocks carry those display names. Checks match on canonical
// capability names, so every tool-name read funnels through canonical().
// Without this the alias split silently killed most checks: worktree-first
// waited for "run_command" while the registry only ever emitted "Bash".
var (
	aliasMu          sync.RWMutex
	aliasToCanonical = map[string]string{}
)

// SetDisplayAliases records the canonical→display alias table (as exported by
// the capability registry) for reverse lookup. Called at watchdog build time;
// safe to call repeatedly.
func SetDisplayAliases(canonicalToDisplay map[string]string) {
	aliasMu.Lock()
	defer aliasMu.Unlock()
	for c, d := range canonicalToDisplay {
		if d != "" && d != c {
			aliasToCanonical[d] = c
		}
	}
}

// canonical maps a display tool name to its canonical capability name.
// Unknown names pass through unchanged.
func canonical(name string) string {
	aliasMu.RLock()
	defer aliasMu.RUnlock()
	if c, ok := aliasToCanonical[name]; ok {
		return c
	}
	return name
}

package server

import (
	"context"

	"cercano/source/server/internal/capabilities/builtins"
	"cercano/source/server/internal/dispatch"
	"cercano/source/server/internal/watchdog"
	"cercano/source/server/pkg/config"
)

// buildWatchdog constructs the protocol-supervision watchdog from the current
// config. Returns nil when disabled (the default), in which case the server
// behaves exactly as if the watchdog did not exist. dispatchEngine must already
// be set — the fast-model OneShot lane routes through it.
func (s *Server) buildWatchdog() *watchdog.Watchdog {
	cfg := s.cfgSvc.Get()
	return s.buildWatchdogFrom(cfg.Watchdog, cfg.Models)
}

// buildWatchdogFrom constructs the watchdog from already-read config sections.
// Lock-free: callers that already hold a config snapshot (UpdateConfig) call
// this directly with the values they have.
func (s *Server) buildWatchdogFrom(wc config.WatchdogConfig, mc config.ModelsConfig) *watchdog.Watchdog {
	if !wc.Enabled {
		return nil
	}

	mode := watchdog.ModeChallenge
	if wc.Mode == "strict" {
		mode = watchdog.ModeStrict
	}

	// Checks match canonical capability names; the standalone registry emits
	// display aliases (Edit, Bash, …). Teach the watchdog the reverse map.
	watchdog.SetDisplayAliases(builtins.AgentAliases())

	// Map configured check names to Check implementations. Unknown names are
	// future checks — skip them silently rather than failing construction. An
	// empty resulting slice is fine: the watchdog then always allows.
	var checks []watchdog.Check
	for _, name := range wc.Checks {
		switch name {
		case "systematic-debugging", "debug-loop":
			checks = append(checks, watchdog.DebugLoopCheck())
		case "design-decisions":
			checks = append(checks, watchdog.DesignDecisionsCheck())
		case "commit-checkpoint":
			checks = append(checks, watchdog.CommitCheckpointCheck())
		case "plain-english":
			checks = append(checks, watchdog.PlainEnglishCheck())
		case "worktree-first":
			checks = append(checks, watchdog.WorktreeFirstCheck())
		case "follow-through":
			checks = append(checks, watchdog.FollowThroughCheck())
		}
	}

	// OneShot is the fast-model handle the checks call, running on the
	// co-processor lane (dispatch.RoleCoproc). Model resolution: explicit
	// watchdog.model config wins, else the models taxonomy's fast_light_text
	// tier (open side — this lane is local), else the lane's own default.
	// Resolved at build time; a models-section change takes effect on the
	// next watchdog rebuild (config reload / watchdog-field update).
	oneShotModel := watchdogModelFor(wc, mc)
	oneShot := func(ctx context.Context, prompt string) (string, error) {
		res, err := s.toolSvc.Engine().Dispatch(ctx, dispatch.Spec{
			Mode:          dispatch.OneShot,
			Role:          dispatch.RoleCoproc,
			Prompt:        prompt,
			ModelOverride: oneShotModel, // "" → RoleCoproc model resolution (the lightweight lane)
			Source:        "watchdog",
		})
		if err != nil {
			return "", err
		}
		return res.Text, nil
	}

	// EscalateAfter 0 is normalized to 2 inside watchdog.New — don't re-default.
	return watchdog.New(watchdog.Config{Mode: mode, EscalateAfter: wc.EscalateAfter}, checks, oneShot)
}

// InitWatchdog builds the watchdog from config once at startup. Call after the
// dispatch engine is set (the OneShot lane depends on it).
func (s *Server) InitWatchdog() { s.watchdog = s.buildWatchdog() }

