	a := Action{Kind: "tool_call", ToolName: "run_command", ToolArgs: []byte(`{"cmd":["bash","-lc","go test ./..."],"cwd":"/repo"}`)}
	if ch.Applies(a) {
		t.Fatal("ordinary tests should be governed by verification-strategy, not compute-before-simulate")
	}
