) Resolver {
	return &service{
		cfgSvc:       cfgSvc,
		openProvider: openProvider,
		router:       router,
		coordinator:  coordinator,
		cloudFactory: cloudFactory,
		registry:     registry,
		syncMeridian: syncMeridian,
		usageSink:    usageSink,
	}
}

