package config

// This file holds the CLOSED-cloud cost/quality taxonomy. Unlike the
// capability tiers (ModelTiers, which also cover open/local models), cost
// tiers exist only on the cloud side: each vendor maps economy/standard/
// premium to its own concrete model ids, because a model id is vendor-owned —
// "premium" resolves to a different actual model per vendor. Open/local models
// keep the capability-tier open slots and are not represented here.
// Design: docs/features/agent-capabilities/dispatch-engine/design.md §7.

// CostTier names a provider-neutral cost/quality band for closed cloud models.
type CostTier string

const (
	CostEconomy  CostTier = "economy"
	CostStandard CostTier = "standard"
	CostPremium  CostTier = "premium"
)

// Flavor wire strings mirrored from internal/cloudfactory. Duplicated as
// literals here (not imported) because cloudfactory imports this package —
// importing it back would cycle. Keep in sync with cloudfactory/factory.go.
const (
	flavorMessages        = "messages"
	flavorChatCompletions = "chat_completions"
	flavorResponses       = "responses"
	flavorBedrock         = "bedrock"
)

// CostTierModel is the model id serving one vendor cost tier. Empty = unset.
type CostTierModel struct {
	Model string `yaml:"model"`
}

// VendorCostTiers is one vendor's economy/standard/premium model lineup.
type VendorCostTiers struct {
	Economy  CostTierModel `yaml:"economy"`
	Standard CostTierModel `yaml:"standard"`
	Premium  CostTierModel `yaml:"premium"`
}

// tier returns the CostTierModel for t (zero value for an unknown tier).
func (v VendorCostTiers) tier(t CostTier) CostTierModel {
	switch t {
	case CostEconomy:
		return v.Economy
	case CostStandard:
		return v.Standard
	case CostPremium:
		return v.Premium
	}
	return CostTierModel{}
}

// CloudCostProfiles maps a vendor name (anthropic|openai|google|...) to its
// cost-tier model lineup.
type CloudCostProfiles struct {
	Providers map[string]VendorCostTiers `yaml:"providers"`
}

// ModelProfiles is the closed-cloud cost/quality taxonomy. The open/local side
// is deliberately absent — local models keep the capability-tier open slots.
type ModelProfiles struct {
	Cloud CloudCostProfiles `yaml:"cloud"`
}

// ResolveCloud returns the model id serving vendor+tier; ok=false when the
// vendor is unknown or that tier is unset.
func (m ModelProfiles) ResolveCloud(vendor string, tier CostTier) (string, bool) {
	if vendor == "" {
		return "", false
	}
	vt, ok := m.Cloud.Providers[vendor]
	if !ok {
		return "", false
	}
	if id := vt.tier(tier).Model; id != "" {
		return id, true
	}
	return "", false
}

// HasVendor reports whether a cost table is configured for vendor.
func (m ModelProfiles) HasVendor(vendor string) bool {
	if vendor == "" || m.Cloud.Providers == nil {
		return false
	}
	_, ok := m.Cloud.Providers[vendor]
	return ok
}

// DeepCopy returns an independent copy — the Providers map is reallocated so a
// config snapshot never aliases the source.
func (m ModelProfiles) DeepCopy() ModelProfiles {
	out := ModelProfiles{}
	if m.Cloud.Providers != nil {
		out.Cloud.Providers = make(map[string]VendorCostTiers, len(m.Cloud.Providers))
		for k, v := range m.Cloud.Providers {
			out.Cloud.Providers[k] = v
		}
	}
	return out
}

// CostTierForCapability maps a capability Tier to the cloud cost tier used when
// the active provider is a closed cloud vendor. The capability tier names the
// strength class; on the cloud side that becomes a cost/quality choice:
//
//	most_capable                 -> premium
//	everyday                     -> standard
//	fast_light / fast_light_text -> economy
//
// The embedding tier has no cloud cost-tier mapping (ok=false).
func CostTierForCapability(t Tier) (CostTier, bool) {
	switch t {
	case TierMostCapable:
		return CostPremium, true
	case TierEveryday:
		return CostStandard, true
	case TierFastLight, TierFastLightText:
		return CostEconomy, true
	}
	return "", false
}

// Vendor returns the cloud vendor whose cost table this profile draws from:
// the explicit Provider field when set, else inferred from the wire shape.
func (p CloudProfile) Vendor() string {
	if p.Provider != "" {
		return p.Provider
	}
	return inferProviderVendor(p)
}

// inferProviderVendor derives a cloud profile's vendor from its wire shape when
// the explicit Provider field is empty: responses -> openai; messages ->
// anthropic; bedrock -> anthropic (Anthropic models on Bedrock);
// chat_completions -> the Backend name (openai|gemini|groq|...) or openai when
// unspecified. Returns "" when nothing is known.
func inferProviderVendor(p CloudProfile) string {
	switch p.Flavor {
	case flavorResponses:
		return "openai"
	case flavorMessages:
		return "anthropic"
	case flavorBedrock:
		return "anthropic"
	case flavorChatCompletions:
		if p.Backend != "" {
			return p.Backend
		}
		return "openai"
	}
	return ""
}

