package research

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"time"
)

// Pipeline orchestrates the full deep research flow.
type Pipeline struct {
	model      ModelCaller
	dispatcher *SearchDispatcher
	fetcher    URLFetcher
}

// NewPipeline creates a new deep research pipeline.
func NewPipeline(model ModelCaller, dispatcher *SearchDispatcher, fetcher URLFetcher) *Pipeline {
	return &Pipeline{
		model:      model,
		dispatcher: dispatcher,
		fetcher:    fetcher,
	}
}

// RunConfig holds the parameters for a research run.
type RunConfig struct {
	Topic      string
	Intent     string
	Depth      string // "survey", "standard", or "deep"
	DateRange  string
	Sources    []string // user override, empty for auto
	OutputDir  string   // write report to this directory if set
	ProjectDir string
	Phase      string // "plan", "search", "analyze", "synthesize", or "" for all
	Progress   ProgressFunc
}

// SuggestedNext holds structured metadata for the host agent to auto-invoke deeper research.
type SuggestedNext struct {
	Action string            `json:"action"`
	Tool   string            `json:"tool"`
	Params map[string]string `json:"params"`
	Reason string            `json:"reason"`
}

// PhaseResult holds the output of a single phase.
type PhaseResult struct {
	Phase                string // which phase just completed
	NextPhase            string // what to run next ("" if done)
	Summary              string // human-readable summary for the host
	OutputDir            string
	FindingsCount        int
	ChasedCount          int
	SourcesSearched      int
	ContentTokensAvoided int
	Report               string         // full report, only set on final phase
	SuggestedNext        *SuggestedNext // structured hint for host to deepen research
}

// Run executes the pipeline — either a single phase or all phases.
func (p *Pipeline) Run(ctx context.Context, cfg RunConfig) (*PhaseResult, error) {
	depth := cfg.Depth
	if depth == "" {
		depth = "standard"
	}
	rcfg := DefaultConfig(depth)

	// Determine output directory
	outputDir := cfg.OutputDir
	if outputDir == "" {
		base := cfg.ProjectDir
		if base == "" {
			base, _ = os.Getwd()
		}
		outputDir = filepath.Join(base, "scratch", "research", slugifyTopic(cfg.Topic))
	}

	progress := NewProgressTracker(outputDir)
	progress.SetProgressFunc(cfg.Progress)
	sidecar := NewSidecar(outputDir)

	// Check for existing state
	var state *ResearchState
	if sidecar.Exists() {
		loaded, err := sidecar.Load()
		if err == nil && loaded.Version == CurrentStateVersion {
			if loaded.IsInProgress() {
				state = loaded // resume from crash
			} else if DepthOrder(depth) > DepthOrder(loaded.Depth) {
				state = loaded // incremental deepening
			} else {
				return &PhaseResult{
					Phase:   "all",
					Summary: fmt.Sprintf("Research already at depth '%s' (requested '%s'). To re-run, delete research_state.json in %s.", loaded.Depth, depth, outputDir),
				}, nil
			}
		}
	}

	if state == nil {
		state = NewState(cfg.Topic, cfg.Intent, depth, cfg.DateRange)
	} else {
		state.Depth = depth // upgrade depth level
	}

	phase := cfg.Phase
	if phase == "" {
		phase = "all"
	}

	switch phase {
	case "plan":
		return p.runPlan(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
	case "search":
		return p.runSearch(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
	case "analyze":
		return p.runAnalyze(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
	case "synthesize":
		return p.runSynthesize(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
	case "all":
		return p.runAll(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
	default:
		return nil, fmt.Errorf("unknown phase: %s (use plan, search, analyze, synthesize, or omit for all)", phase)
	}
}

// --- Phase: Plan ---

func (p *Pipeline) runPlan(ctx context.Context, cfg RunConfig, state *ResearchState, sidecar *Sidecar, rcfg DeepResearchConfig, progress *ProgressTracker, outputDir string) (*PhaseResult, error) {
	progress.Update("Planning", "Identifying relevant sources...")

	var plan *ResearchPlan
	var err error

	if state.Plan != nil && len(state.Plan.Sources) > 0 {
		// Incremental deepening: expand existing plan with complementary sources
		newSources, expErr := PlanExpansion(ctx, p.model, cfg.Topic, cfg.Intent, state.Depth, cfg.DateRange, state.Plan.Sources, rcfg.MaxSources)
		if expErr != nil {
			return nil, fmt.Errorf("plan expansion: %w", expErr)
		}
		plan = state.Plan
		plan.Depth = state.Depth
		plan.Sources = append(plan.Sources, newSources...)
	} else if len(cfg.Sources) > 0 {
		plan, err = PlanWithOverride(ctx, p.model, cfg.Topic, cfg.Intent, state.Depth, cfg.DateRange, cfg.Sources)
	} else {
		plan, err = PlanSources(ctx, p.model, cfg.Topic, cfg.Intent, state.Depth, cfg.DateRange)
	}
	if err != nil {
		return nil, fmt.Errorf("source planning: %w", err)
	}

	state.Plan = plan
	state.Progress.Phase = "plan"
	state.Progress.PhaseStartedAt = time.Now()
	sidecar.Save(state)

	// Build summary
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("**Source plan for:** %s\n\n", cfg.Topic))
	sb.WriteString(fmt.Sprintf("Selected %d sources:\n", len(plan.Sources)))
	for i, src := range plan.Sources {
		sb.WriteString(fmt.Sprintf("%d. **%s** — %s\n", i+1, src.Name, src.Reason))
		for _, q := range src.Queries {
			sb.WriteString(fmt.Sprintf("   - `%s`\n", q))
		}
	}
	sb.WriteString(fmt.Sprintf("\nNext step: run with `phase: \"search\"` to search these sources."))
	sb.WriteString(fmt.Sprintf("\nTo adjust sources, re-run with `sources: [\"Source1\", \"Source2\"]`"))

	return &PhaseResult{
		Phase:           "plan",
		NextPhase:       "search",
		Summary:         sb.String(),
		OutputDir:       outputDir,
		SourcesSearched: len(plan.Sources),
	}, nil
}

// --- Phase: Search ---

func (p *Pipeline) runSearch(ctx context.Context, cfg RunConfig, state *ResearchState, sidecar *Sidecar, rcfg DeepResearchConfig, progress *ProgressTracker, outputDir string) (*PhaseResult, error) {
	plan := state.Plan
	if plan == nil || len(plan.Sources) == 0 {
		return nil, fmt.Errorf("no research plan found — run with phase: \"plan\" first")
	}

	progress.Update("Searching", fmt.Sprintf("Searching %d sources and prefetching content concurrently...", len(plan.Sources)))

	// Search + prefetch content in parallel
	pubs, contentMap := p.dispatcher.SearchAndPrefetch(ctx, plan, rcfg.MaxPrimaryResults, p.fetcher)

	// If deepening, skip publications already in state
	if len(state.SearchResults) > 0 {
		existingURLs := make(map[string]bool, len(state.SearchResults))
		for _, existing := range state.SearchResults {
			existingURLs[existing.URL] = true
		}
		var newPubs []Publication
		for _, pub := range pubs {
			if !existingURLs[pub.URL] {
				newPubs = append(newPubs, pub)
			}
		}
		state.SearchResults = append(state.SearchResults, newPubs...)
		// Merge content caches
		if state.ContentCache == nil {
			state.ContentCache = make(map[string]string)
		}
		for k, v := range contentMap {
			state.ContentCache[k] = v
		}
		pubs = state.SearchResults // for summary counts
	} else {
		state.SearchResults = pubs
		state.ContentCache = contentMap
	}

	state.Progress.Phase = "search"
	state.Progress.PhaseStartedAt = time.Now()
	sidecar.Save(state)

	// Build summary
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("**Search results for:** %s\n\n", cfg.Topic))
	sb.WriteString(fmt.Sprintf("Found **%d results** across %d sources:\n\n", len(pubs), len(plan.Sources)))

	// Group by source
	bySource := map[string]int{}
	for _, pub := range pubs {
		bySource[pub.Source]++
	}
	for src, count := range bySource {
		sb.WriteString(fmt.Sprintf("- **%s:** %d results\n", src, count))
	}
	sb.WriteString("\nTop results:\n")
	limit := 10
	if limit > len(pubs) {
		limit = len(pubs)
	}
	for i, pub := range pubs[:limit] {
		sb.WriteString(fmt.Sprintf("%d. [%s] %s\n", i+1, pub.Source, pub.Title))
	}
	if len(pubs) > limit {
		sb.WriteString(fmt.Sprintf("   ... and %d more\n", len(pubs)-limit))
	}
	sb.WriteString(fmt.Sprintf("\nNext step: run with `phase: \"analyze\"` to analyze these findings."))

	return &PhaseResult{
		Phase:           "search",
		NextPhase:       "analyze",
		Summary:         sb.String(),
		OutputDir:       outputDir,
		SourcesSearched: len(plan.Sources),
		FindingsCount:   len(pubs),
	}, nil
}

// --- Phase: Analyze ---

func (p *Pipeline) runAnalyze(ctx context.Context, cfg RunConfig, state *ResearchState, sidecar *Sidecar, rcfg DeepResearchConfig, progress *ProgressTracker, outputDir string) (*PhaseResult, error) {
	pubs := state.SearchResults
	if len(pubs) == 0 {
		return nil, fmt.Errorf("no search results found — run with phase: \"search\" first")
	}

	prefetched := state.ContentCache

	// If deepening, only analyze pubs not already in findings
	var pubsToAnalyze []Publication
	if len(state.Findings) > 0 {
		analyzedURLs := make(map[string]bool, len(state.Findings))
		for _, f := range state.Findings {
			analyzedURLs[f.Publication.URL] = true
		}
		for _, pub := range pubs {
			if !analyzedURLs[pub.URL] {
				pubsToAnalyze = append(pubsToAnalyze, pub)
			}
		}
	} else {
		pubsToAnalyze = pubs
	}

	progress.Update("Analyzing", fmt.Sprintf("Processing %d results (3 passes each)...", len(pubsToAnalyze)))
	newFindings := AnalyzeAllWithPrefetch(ctx, p.model, p.fetcher, pubsToAnalyze, prefetched, cfg.Intent, rcfg, progress)

	// Chase references on new findings
	if len(newFindings) > 0 {
		refCount := countCitedRefs(newFindings, rcfg)
		if refCount > 0 {
			progress.Update("Chasing", fmt.Sprintf("Following %d cited references...", refCount))
			chased := ChaseReferences(ctx, p.model, p.dispatcher, p.fetcher, newFindings, cfg.Intent, rcfg)
			newFindings = append(newFindings, chased...)
		}
	}

	// Merge new findings with existing
	allFindings := append(state.Findings, newFindings...)

	// If deepening and we have existing findings, re-analyze middle-scored ones
	if len(state.Findings) > 0 && len(newFindings) > 0 {
		progress.Update("Re-analyzing", "Re-scoring middle-range findings with new context...")
		allFindings = ReAnalyzeMiddleFindings(ctx, p.model, allFindings, cfg.Intent)
	}

	state.Findings = allFindings
	state.Progress.Phase = "analyze"
	state.Progress.PhaseStartedAt = time.Now()
	sidecar.Save(state)

	primaryCount, chasedCount := countFindings(allFindings)

	// Build summary
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("**Analysis complete for:** %s\n\n", cfg.Topic))
	sb.WriteString(fmt.Sprintf("Analyzed **%d findings** (%d primary, %d discovered via references)\n\n", primaryCount+chasedCount, primaryCount, chasedCount))

	sb.WriteString("Top findings by relevance:\n")
	sorted := make([]AnnotatedFinding, len(allFindings))
	copy(sorted, allFindings)
	sortFindings(sorted)
	limit := 10
	if limit > len(sorted) {
		limit = len(sorted)
	}
	for i, f := range sorted[:limit] {
		stars := strings.Repeat("\u2b50", f.RelevanceScore)
		sb.WriteString(fmt.Sprintf("%d. %s [%s] %s\n", i+1, stars, f.Publication.Source, f.Publication.Title))
		if f.Summary != "" {
			summary := f.Summary
			if len(summary) > 150 {
				summary = summary[:150] + "..."
			}
			sb.WriteString(fmt.Sprintf("   %s\n", summary))
		}
	}
	sb.WriteString(fmt.Sprintf("\nNext step: run with `phase: \"synthesize\"` to generate the final report."))

	// Track content for telemetry
	totalContent := 0
	for _, f := range allFindings {
		totalContent += len(f.Publication.Abstract)
	}

	return &PhaseResult{
		Phase:                "analyze",
		NextPhase:            "synthesize",
		Summary:              sb.String(),
		OutputDir:            outputDir,
		FindingsCount:        primaryCount + chasedCount,
		ChasedCount:          chasedCount,
		ContentTokensAvoided: totalContent / 4,
	}, nil
}

// --- Phase: Synthesize ---

func (p *Pipeline) runSynthesize(ctx context.Context, cfg RunConfig, state *ResearchState, sidecar *Sidecar, rcfg DeepResearchConfig, progress *ProgressTracker, outputDir string) (*PhaseResult, error) {
	findings := state.Findings
	if len(findings) == 0 {
		return nil, fmt.Errorf("no findings found — run with phase: \"analyze\" first")
	}

	plan := state.Plan
	if plan == nil {
		plan = &ResearchPlan{Topic: cfg.Topic, Intent: cfg.Intent}
	}

	progress.Update("Synthesizing", "Generating executive summary...")
	var sections ReportSections
	sections.ExecutiveSummary, _ = GenerateExecutiveSummary(ctx, p.model, findings, cfg.Intent)

	progress.Update("Synthesizing", "Generating narrative synthesis...")
	sections.Synthesis, _ = Synthesize(ctx, p.model, findings, cfg.Intent)

	progress.Update("Synthesizing", "Detecting contradictions...")
	sections.Contradictions, _ = DetectContradictions(ctx, p.model, findings)

	progress.Update("Synthesizing", "Analyzing gaps...")
	sections.GapAnalysis, _ = AnalyzeGaps(ctx, p.model, findings, cfg.Intent)

	progress.Update("Synthesizing", "Generating reading order and follow-ups...")
	sections.ReadingOrder, _ = RecommendReadingOrder(ctx, p.model, findings, cfg.Intent)
	if sections.GapAnalysis != "" {
		sections.FollowUpQueries, _ = SuggestFollowUp(ctx, p.model, sections.GapAnalysis, cfg.Intent)
	}

	state.Sections = &sections
	state.Progress = ProgressState{
		Phase:       "complete",
		CompletedAt: time.Now(),
	}
	sidecar.Save(state)

	// Compile and write report
	progress.Update("Compiling", "Writing report files...")
	primaryCount, chasedCount := countFindings(findings)
	report := CompileReport(plan, findings, sections)

	if err := WriteReport(outputDir, plan, findings, sections); err != nil {
		return nil, fmt.Errorf("failed to write report: %w", err)
	}

	progress.Done(primaryCount+chasedCount, len(plan.Sources))

	// Build summary
	var sb strings.Builder
	sb.WriteString(fmt.Sprintf("**Research complete:** %s\n\n", cfg.Topic))
	sb.WriteString(fmt.Sprintf("Report written to: `%s`\n\n", outputDir))
	sb.WriteString(fmt.Sprintf("- **Sources:** %d\n", len(plan.Sources)))
	sb.WriteString(fmt.Sprintf("- **Findings:** %d (%d primary, %d references)\n", primaryCount+chasedCount, primaryCount, chasedCount))
	sb.WriteString("\nFiles:\n")
	sb.WriteString("- `README.md` — index with table of contents\n")
	sb.WriteString("- `findings/` — individual finding files\n")
	sb.WriteString("- `references/` — discovered references\n")
	sb.WriteString("- `synthesis.md` — synthesis, gaps, follow-ups\n")
	sb.WriteString("- `source_plan.md` — sources and queries used\n")

	if sections.ExecutiveSummary != "" {
		sb.WriteString(fmt.Sprintf("\n**Executive Summary:**\n%s", sections.ExecutiveSummary))
	}

	totalContent := 0
	for _, f := range findings {
		totalContent += len(f.Publication.Abstract)
	}

	var suggested *SuggestedNext
	currentDepth := state.Depth
	if currentDepth == "survey" || currentDepth == "standard" {
		nextDepth := "standard"
		if currentDepth == "standard" {
			nextDepth = "deep"
		}
		suggested = &SuggestedNext{
			Action: "deepen",
			Tool:   "cercano_deep_research",
			Params: map[string]string{
				"topic":      cfg.Topic,
				"intent":     cfg.Intent,
				"depth":      nextDepth,
				"output_dir": outputDir,
			},
			Reason: fmt.Sprintf("%s found %d findings across %d sources. %s depth adds broader coverage and reference chasing.",
				currentDepth, primaryCount+chasedCount, len(plan.Sources), nextDepth),
		}
	}

	return &PhaseResult{
		Phase:                "synthesize",
		NextPhase:            "",
		Summary:              sb.String(),
		OutputDir:            outputDir,
		FindingsCount:        primaryCount + chasedCount,
		ChasedCount:          chasedCount,
		SourcesSearched:      len(plan.Sources),
		ContentTokensAvoided: totalContent / 4,
		Report:               report,
		SuggestedNext:        suggested,
	}, nil
}

// --- Run All (backward compat) ---

func (p *Pipeline) runAll(ctx context.Context, cfg RunConfig, state *ResearchState, sidecar *Sidecar, rcfg DeepResearchConfig, progress *ProgressTracker, outputDir string) (*PhaseResult, error) {
	// Plan
	planResult, err := p.runPlan(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
	if err != nil {
		return nil, err
	}

	// Search
	searchResult, err := p.runSearch(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
	if err != nil {
		return nil, err
	}
	if searchResult.FindingsCount == 0 {
		return &PhaseResult{
			Phase:   "all",
			Summary: fmt.Sprintf("No results found across %d sources.", planResult.SourcesSearched),
		}, nil
	}

	// Analyze
	_, err = p.runAnalyze(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
	if err != nil {
		return nil, err
	}

	// Synthesize
	return p.runSynthesize(ctx, cfg, state, sidecar, rcfg, progress, outputDir)
}

// --- Helpers ---

func countFindings(findings []AnnotatedFinding) (primary, chased int) {
	for _, f := range findings {
		if f.DiscoveredVia != "" {
			chased++
		} else {
			primary++
		}
	}
	return
}

func countCitedRefs(findings []AnnotatedFinding, cfg DeepResearchConfig) int {
	count := 0
	for _, f := range findings {
		c := len(f.CitedRefs)
		if c > cfg.MaxChasedPerFinding {
			c = cfg.MaxChasedPerFinding
		}
		count += c
	}
	if count > cfg.MaxChasedTotal {
		count = cfg.MaxChasedTotal
	}
	return count
}

var nonAlphaNumPipeline = regexp.MustCompile(`[^a-z0-9]+`)

func slugifyTopic(topic string) string {
	s := strings.ToLower(topic)
	s = nonAlphaNumPipeline.ReplaceAllString(s, "-")
	s = strings.Trim(s, "-")
	if len(s) > 50 {
		s = s[:50]
		if i := strings.LastIndex(s, "-"); i > 20 {
			s = s[:i]
		}
	}
	return s
}

// Package research implements deep multi-source research with ranked, annotated findings.
package research

import (
	"context"
	"time"
)

// ModelCaller abstracts calling the local model for inference.
type ModelCaller interface {
	Call(ctx context.Context, prompt string) (string, error)
}

// SearchProvider abstracts searching a source for publications.
type SearchProvider interface {
	Search(ctx context.Context, query string, maxResults int) ([]SearchResult, error)
}

// URLFetcher abstracts fetching URL content.
type URLFetcher interface {
	FetchURL(url string) (*FetchResult, error)
}

// SearchResult is a single search hit.
type SearchResult struct {
	URL     string
	Title   string
	Snippet string
}

// FetchResult is the content fetched from a URL.
type FetchResult struct {
	URL     string
	Title   string
	Content string
}

// Publication represents a discovered work from any source.
type Publication struct {
	Title    string
	Authors  string
	Source   string // e.g. "PubMed", "arXiv", "Wired"
	URL      string
	Date     string
	Abstract string
	DOI      string
	Metadata map[string]string // source-specific fields
}

// AnnotatedFinding is a publication with analysis relative to the user's intent.
type AnnotatedFinding struct {
	Publication    Publication
	Summary        string
	KeyFindings    []string // concrete bullet points of key facts
	WhyItMatters   string
	HowToUse       string
	RelevanceScore int    // 1-5
	ImpactRating   string // "low", "medium", "high"
	DiscoveredVia  string // parent finding title if chased, empty for primary
	CitedRefs      []CitedReference
}

// CitedReference is a reference extracted from a finding's content.
type CitedReference struct {
	Title  string
	Why    string // why it's relevant to the intent
	Source string // suggested source to search (e.g. "PubMed")
}

// Source represents a research source to search.
type Source struct {
	Name    string   // e.g. "PubMed", "Wired"
	Type    string   // "api" or "web"
	Site    string   // site domain for web-scoped DDG search (e.g. "wired.com")
	Queries []string // tailored search queries
	Reason  string   // why this source is relevant
}

// ResearchPlan is the output of source planning.
type ResearchPlan struct {
	Topic     string
	Intent    string
	Depth     string // "survey", "standard", or "deep"
	DateRange string
	Sources   []Source
}

// ResearchProgress tracks the state of a running research job.
type ResearchProgress struct {
	Phase     string
	Step      string
	Current   int
	Total     int
	StartedAt time.Time
}

// ReportSections holds all generated sections for the final report.
type ReportSections struct {
	ExecutiveSummary string
	Synthesis        string
	Contradictions   string
	GapAnalysis      string
	ReadingOrder     []string
	FollowUpQueries  []string
}

// DeepResearchConfig holds configuration for a research run.
type DeepResearchConfig struct {
	MaxPrimaryResults   int // max results per source search
	MaxChasedTotal      int // max total chased references
	MaxChasedPerFinding int // max chased references per finding
	PageTruncateChars   int // max chars per fetched page
	AnalysisTruncate    int // max chars sent to model for analysis
	MaxQueriesPerSource int // max queries to run per source
	MaxSources          int // max sources to search
}

// CurrentStateVersion is the version written into ResearchState.Version.
const CurrentStateVersion = 1

// ResearchState is the persistent sidecar written to research_state.json.
type ResearchState struct {
	Version       int                `json:"version"`
	Depth         string             `json:"depth"`
	Topic         string             `json:"topic"`
	Intent        string             `json:"intent"`
	DateRange     string             `json:"date_range,omitempty"`
	Plan          *ResearchPlan      `json:"plan,omitempty"`
	SearchResults []Publication      `json:"search_results,omitempty"`
	ContentCache  map[string]string  `json:"content_cache,omitempty"`
	Findings      []AnnotatedFinding `json:"findings,omitempty"`
	Sections      *ReportSections    `json:"sections,omitempty"`
	Progress      ProgressState      `json:"progress"`
	CreatedAt     time.Time          `json:"created_at"`
	UpdatedAt     time.Time          `json:"updated_at"`
}

// ProgressFunc receives semantic research progress snapshots.
type ProgressFunc func(ProgressState)

// ProgressState is the serializable progress snapshot in the sidecar.
type ProgressState struct {
	Phase            string    `json:"phase"`
	Step             string    `json:"step,omitempty"`
	Current          int       `json:"current,omitempty"`
	Total            int       `json:"total,omitempty"`
	FindingsAccepted int       `json:"findings_accepted"`
	RunStartedAt     time.Time `json:"run_started_at"`
	PhaseStartedAt   time.Time `json:"phase_started_at,omitempty"`
	CompletedAt      time.Time `json:"completed_at,omitempty"`
}

// DepthOrder returns a numeric ordering for a depth string (survey=1, standard=2, deep=3, unknown=0).
func DepthOrder(depth string) int {
	switch depth {
	case "survey":
		return 1
	case "standard":
		return 2
	case "deep":
		return 3
	default:
		return 0
	}
}

// DefaultConfig returns config for the given depth: "survey", "standard", or "deep".
// An empty string defaults to "standard".
func DefaultConfig(depth string) DeepResearchConfig {
	if depth == "" {
		depth = "standard"
	}
	switch depth {
	case "survey":
		return DeepResearchConfig{
			MaxPrimaryResults:   3,
			MaxChasedTotal:      0,
			MaxChasedPerFinding: 0,
			PageTruncateChars:   8000,
			AnalysisTruncate:    10000,
			MaxQueriesPerSource: 2,
			MaxSources:          3,
		}
	case "deep":
		return DeepResearchConfig{
			MaxPrimaryResults:   6,
			MaxChasedTotal:      50,
			MaxChasedPerFinding: 5,
			PageTruncateChars:   12000,
			AnalysisTruncate:    15000,
			MaxQueriesPerSource: 3,
			MaxSources:          5,
		}
	default: // "standard" and anything unrecognised
		return DeepResearchConfig{
			MaxPrimaryResults:   4,
			MaxChasedTotal:      15,
			MaxChasedPerFinding: 3,
			PageTruncateChars:   10000,
			AnalysisTruncate:    12000,
			MaxQueriesPerSource: 3,
			MaxSources:          4,
		}
	}
}

package research

import (
	"encoding/json"
	"os"
	"path/filepath"
	"time"
)

const sidecarFilename = "research_state.json"

// Sidecar manages the persistent research_state.json in an output directory.
type Sidecar struct {
	dir string
}

// NewSidecar creates a Sidecar for the given output directory.
func NewSidecar(outputDir string) *Sidecar {
	return &Sidecar{dir: outputDir}
}

// Path returns the full path to research_state.json.
func (s *Sidecar) Path() string {
	return filepath.Join(s.dir, sidecarFilename)
}

// Exists reports whether research_state.json exists in the output directory.
func (s *Sidecar) Exists() bool {
	_, err := os.Stat(s.Path())
	return err == nil
}

// Load reads and unmarshals the sidecar from disk.
func (s *Sidecar) Load() (*ResearchState, error) {
	data, err := os.ReadFile(s.Path())
	if err != nil {
		return nil, err
	}
	var state ResearchState
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, err
	}
	return &state, nil
}

// Save marshals state to JSON and writes it to disk, updating UpdatedAt first.
// It creates the output directory if it does not exist.
func (s *Sidecar) Save(state *ResearchState) error {
	if err := os.MkdirAll(s.dir, 0755); err != nil {
		return err
	}
	state.UpdatedAt = time.Now()
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return err
	}
	return os.WriteFile(s.Path(), data, 0644)
}

// IsInProgress reports whether the research run is still in progress.
// A state is in-progress when its Phase is non-empty and not "complete".
func (rs *ResearchState) IsInProgress() bool {
	return rs.Progress.Phase != "" && rs.Progress.Phase != "complete"
}

// NewState constructs a fresh ResearchState ready to begin the plan phase.
func NewState(topic, intent, depth, dateRange string) *ResearchState {
	now := time.Now()
	return &ResearchState{
		Version:   CurrentStateVersion,
		Depth:     depth,
		Topic:     topic,
		Intent:    intent,
		DateRange: dateRange,
		Progress: ProgressState{
			Phase:        "plan",
			RunStartedAt: now,
		},
		CreatedAt: now,
		UpdatedAt: now,
	}
}

package web

import (
	"context"
	"fmt"
	"strings"
	"sync"
)

// ModelCaller abstracts calling the local model. Implemented by the MCP server
// using the gRPC client; mockable for tests.
type ModelCaller interface {
	Call(ctx context.Context, prompt string) (string, error)
}

// SearchProvider abstracts the search backend. Implemented by Searcher (DDG);
// mockable for tests.
type SearchProvider interface {
	Search(ctx context.Context, query string, maxResults int) ([]SearchResult, error)
}

// URLFetcher abstracts URL fetching. Implemented by Fetcher; mockable for tests.
type URLFetcher interface {
	FetchURL(url string) (*FetchResult, error)
}

// FetchedPage holds a fetched page's content alongside its search metadata.
type FetchedPage struct {
	URL     string
	Title   string
	Content string
}

// ResearchResult is the final output of the research pipeline.
type ResearchResult struct {
	Answer  string
	Sources []string
}

// ResearchProgressFunc receives a coarse phase update as the research pipeline
// advances (e.g. "crafting search queries…", "fetching 4 pages…").
type ResearchProgressFunc func(phase string)

// ResearchPipeline orchestrates the full research flow: query crafting,
// search, fetch, and synthesis via the local model.
type ResearchPipeline struct {
	model    ModelCaller
	searcher SearchProvider
	fetcher  URLFetcher
	progress ResearchProgressFunc
}

// SetProgress registers a callback invoked at each pipeline phase. Optional;
// nil disables progress reporting.
func (p *ResearchPipeline) SetProgress(fn ResearchProgressFunc) { p.progress = fn }

func (p *ResearchPipeline) report(phase string) {
	if p.progress != nil {
		p.progress(phase)
	}
}

// NewResearchPipeline creates a pipeline with the given dependencies.
func NewResearchPipeline(model ModelCaller, searcher SearchProvider, fetcher URLFetcher) *ResearchPipeline {
	return &ResearchPipeline{
		model:    model,
		searcher: searcher,
		fetcher:  fetcher,
	}
}

// CraftQueries asks the local model to generate 2-3 search queries for the
// user's research question. Falls back to the original query if parsing fails.
func (p *ResearchPipeline) CraftQueries(ctx context.Context, question string) ([]string, error) {
	prompt := fmt.Sprintf(`Generate 2-3 concise web search queries to answer this question. Output ONLY the queries, one per line, numbered (1. 2. 3.). No explanations.

Question: %s`, question)

	resp, err := p.model.Call(ctx, prompt)
	if err != nil {
		return nil, fmt.Errorf("query crafting failed: %w", err)
	}

	queries := parseNumberedList(resp)
	if len(queries) == 0 {
		// Fallback: use the original question as the search query
		return []string{question}, nil
	}
	return queries, nil
}

// SearchAll runs searches for all queries concurrently and returns combined
// results plus the errors from failed queries. A partial failure is fine —
// the surviving queries still feed the pipeline — but callers must be able
// to tell "every search broke" apart from "the web had nothing to say".
func (p *ResearchPipeline) SearchAll(ctx context.Context, queries []string, maxPerQuery int) ([]SearchResult, []error) {
	var mu sync.Mutex
	var all []SearchResult
	var errs []error
	var wg sync.WaitGroup

	for _, q := range queries {
		wg.Add(1)
		go func(query string) {
			defer wg.Done()
			results, err := p.searcher.Search(ctx, query, maxPerQuery)
			mu.Lock()
			defer mu.Unlock()
			if err != nil {
				errs = append(errs, err)
				return
			}
			all = append(all, results...)
		}(q)
	}
	wg.Wait()
	return all, errs
}

// DeduplicateResults removes duplicate URLs, preserving first occurrence order.
func DeduplicateResults(results []SearchResult) []SearchResult {
	seen := make(map[string]bool)
	var deduped []SearchResult
	for _, r := range results {
		if !seen[r.URL] {
			seen[r.URL] = true
			deduped = append(deduped, r)
		}
	}
	return deduped
}

// FetchAll fetches up to maxResults URLs concurrently and returns their content.
func (p *ResearchPipeline) FetchAll(ctx context.Context, results []SearchResult, maxResults int) []FetchedPage {
	if maxResults <= 0 {
		maxResults = 5
	}
	if len(results) > maxResults {
		results = results[:maxResults]
	}

	var mu sync.Mutex
	var pages []FetchedPage
	var wg sync.WaitGroup

	for _, r := range results {
		wg.Add(1)
		go func(sr SearchResult) {
			defer wg.Done()
			fr, err := p.fetcher.FetchURL(sr.URL)
			if err != nil {
				return // graceful degradation — skip failed fetches
			}
			mu.Lock()
			pages = append(pages, FetchedPage{
				URL:     sr.URL,
				Title:   sr.Title,
				Content: fr.Content,
			})
			mu.Unlock()
		}(r)
	}
	wg.Wait()
	return pages
}

// Synthesize asks the local model to analyze fetched content and produce a
// sourced answer to the original question.
func (p *ResearchPipeline) Synthesize(ctx context.Context, question string, pages []FetchedPage) (string, error) {
	var sb strings.Builder
	for i, page := range pages {
		// Truncate very long pages to keep prompt reasonable
		content := page.Content
		if len(content) > 8000 {
			content = content[:8000] + "\n[...truncated]"
		}
		fmt.Fprintf(&sb, "--- Source %d: %s (%s) ---\n%s\n\n", i+1, page.Title, page.URL, content)
	}

	prompt := fmt.Sprintf(`You are a research assistant. Based on the web sources below, provide a clear, accurate answer to the question. Cite sources by URL where relevant. If the sources don't contain enough information, say so.

Question: %s

%s

Provide your answer now. Include source URLs as citations.`, question, sb.String())

	resp, err := p.model.Call(ctx, prompt)
	if err != nil {
		return "", fmt.Errorf("synthesis failed: %w", err)
	}
	return resp, nil
}

// Run executes the full research pipeline: craft queries → search → deduplicate
// → fetch → synthesize. Returns a distilled answer with source citations.
func (p *ResearchPipeline) Run(ctx context.Context, question string, maxResults int) (*ResearchResult, error) {
	if maxResults <= 0 {
		maxResults = 5
	}

	// Step 1: Craft search queries
	p.report("crafting search queries…")
	queries, err := p.CraftQueries(ctx, question)
	if err != nil {
		return nil, err
	}

	// Step 2: Search all queries in parallel
	p.report(fmt.Sprintf("searching %d queries…", len(queries)))
	allResults, searchErrs := p.SearchAll(ctx, queries, maxResults)

	// Step 3: Deduplicate
	deduped := DeduplicateResults(allResults)
	p.report(fmt.Sprintf("found %d unique results", len(deduped)))
	if len(deduped) == 0 {
		// When every query errored the cause is the search layer, not the
		// query content — surface it instead of a misleading "no results".
		if len(searchErrs) > 0 && len(searchErrs) == len(queries) {
			return nil, fmt.Errorf("all %d searches failed: %w", len(queries), searchErrs[0])
		}
		return nil, fmt.Errorf("no search results found for: %s", question)
	}

	// Step 4: Fetch top pages in parallel
	p.report(fmt.Sprintf("fetching up to %d pages…", maxResults))
	pages := p.FetchAll(ctx, deduped, maxResults)
	if len(pages) == 0 {
		// Fall back: synthesize from snippets only
		for _, r := range deduped {
			pages = append(pages, FetchedPage{
				URL:     r.URL,
				Title:   r.Title,
				Content: r.Snippet,
			})
		}
	}

	// Step 5: Synthesize answer
	p.report(fmt.Sprintf("synthesizing answer from %d sources…", len(pages)))
	answer, err := p.Synthesize(ctx, question, pages)
	if err != nil {
		return nil, err
	}

	// Collect source URLs
	var sources []string
	for _, page := range pages {
		sources = append(sources, page.URL)
	}

	return &ResearchResult{
		Answer:  answer,
		Sources: sources,
	}, nil
}

// FetchURL implements URLFetcher for the existing Fetcher type.
func (f *Fetcher) FetchURL(url string) (*FetchResult, error) {
	return f.Fetch(url)
}

// parseNumberedList extracts items from a numbered list (1. item\n2. item\n...).
func parseNumberedList(text string) []string {
	var items []string
	for _, line := range strings.Split(text, "\n") {
		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}
		// Strip leading number and punctuation: "1. ", "2) ", "1: ", etc.
		for i, c := range line {
			if c >= '0' && c <= '9' {
				continue
			}
			if c == '.' || c == ')' || c == ':' {
				item := strings.TrimSpace(line[i+1:])
				if item != "" {
					items = append(items, item)
				}
				break
			}
			// Not a numbered line — skip
			break
		}
	}
	return items
}

package builtins

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"cercano/source/server/internal/capabilities"
	"cercano/source/server/internal/web"
	"cercano/source/server/pkg/config"
)

type researchCap struct{}

// Research constructs the research capability.
func Research() capabilities.Capability { return researchCap{} }

func (researchCap) Name() string            { return "research" }
func (researchCap) Tier() capabilities.Tier { return capabilities.TierR }

// SurfaceAgent only: the MCP surface keeps its legacy hand-registered
// cercano_research handler; registering here too would collide on that name.
func (researchCap) Surfaces() capabilities.Surface { return capabilities.SurfaceAgent }

func (researchCap) Description() string {
	return "Research a question using web search and local AI analysis. Crafts search queries, searches DuckDuckGo, fetches top results, and synthesizes a sourced answer — all locally. Requires the Python venv (run 'cercano setup' once). Args: {query: string, max_results?: int}."
}
func (researchCap) Schema() capabilities.Schema {
	return capabilities.Schema(`{
		"type": "object",
		"properties": {
			"query":       {"type": "string", "description": "The research question to investigate."},
			"max_results": {"type": "integer", "description": "Maximum search results to fetch and analyze (default 5)."}
		},
		"required": ["query"]
	}`)
}

type researchArgs struct {
	Query      string `json:"query"`
	MaxResults int    `json:"max_results"`
}

func (researchCap) Execute(ctx context.Context, call *capabilities.Call) (*capabilities.Result, error) {
	var a researchArgs
	if err := json.Unmarshal(call.Args, &a); err != nil {
		return nil, fmt.Errorf("research: parse args: %w", err)
	}
	if a.Query == "" {
		return nil, fmt.Errorf("research: 'query' is required")
	}
	if !venvReady() {
		return nil, errors.New("research: " + venvMissingMessage)
	}

	scriptPath, err := searchScriptPath()
	if err != nil {
		return nil, fmt.Errorf("research: search script: %w", err)
	}
	searcher := web.NewSearcher(config.VenvPython(), scriptPath)
	model := &dispatchModelCaller{call: call, source: "research", tier: config.TierFastLightText}
	pipeline := web.NewResearchPipeline(model, searcher, web.NewFetcher())

	activity := newActivityReporter(call, "research", "research")
	maxResults := a.MaxResults
	if maxResults <= 0 {
		maxResults = 5
	}
	activity.Started(fmt.Sprintf("research start: query=%q max_results=%d", a.Query, maxResults))
	activity.Prompt("Query: " + a.Query)
	pipeline.SetProgress(func(phase string) { activity.Progress(phase) })

	result, err := pipeline.Run(ctx, a.Query, a.MaxResults)
	if err != nil {
		activity.Failed(err)
		return nil, fmt.Errorf("research: %w", err)
	}
	activity.Done(fmt.Sprintf("research complete: %d sources", len(result.Sources)))

	var b strings.Builder
	b.WriteString(result.Answer)
	if len(result.Sources) > 0 {
		b.WriteString("\n\nSources:\n")
		for _, src := range result.Sources {
			b.WriteString("- " + src + "\n")
		}
	}
	return capabilities.NewTextResult(b.String()), nil
}

package builtins

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"strings"

	"cercano/source/server/internal/capabilities"
	"cercano/source/server/internal/research"
	"cercano/source/server/internal/web"
	"cercano/source/server/pkg/config"
)

type deepResearchCap struct{}

// DeepResearch constructs the deep_research capability.
func DeepResearch() capabilities.Capability { return deepResearchCap{} }

func (deepResearchCap) Name() string            { return "deep_research" }
func (deepResearchCap) Tier() capabilities.Tier { return capabilities.TierR }

// SurfaceAgent only: the MCP surface keeps its legacy hand-registered
// cercano_deep_research handler; registering here too would collide on that name.
func (deepResearchCap) Surfaces() capabilities.Surface { return capabilities.SurfaceAgent }

func (deepResearchCap) Description() string {
	return "Deep multi-source research. Takes a topic and intent, identifies authoritative sources, systematically searches each, analyzes and ranks findings, chases cited references, and compiles a structured report — all locally. Requires the Python venv (run 'cercano setup' once). Args: {topic: string, intent: string, depth?: \"survey\"|\"standard\"|\"deep\", date_range?: string, sources?: [string], output_dir?: string, phase?: string, model?: string}."
}
func (deepResearchCap) Schema() capabilities.Schema {
	return capabilities.Schema(`{
		"type": "object",
		"properties": {
			"topic":      {"type": "string", "description": "The research topic."},
			"intent":     {"type": "string", "description": "What the research is for — shapes source selection and analysis."},
			"depth":      {"type": "string", "description": "Research depth: \"survey\", \"standard\" (default), or \"deep\"."},
			"date_range": {"type": "string", "description": "Restrict findings to a date range, e.g. \"2024-2026\"."},
			"sources":    {"type": "array", "items": {"type": "string"}, "description": "Source categories to search; empty for automatic selection."},
			"output_dir": {"type": "string", "description": "Write the report and findings as files into this directory."},
			"phase":      {"type": "string", "description": "Run a single phase: \"plan\", \"search\", \"analyze\", or \"synthesize\"; empty runs all."},
			"model":      {"type": "string", "description": "Advisory local model override for the analysis calls."}
		},
		"required": ["topic", "intent"]
	}`)
}

type deepResearchArgs struct {
	Topic     string   `json:"topic"`
	Intent    string   `json:"intent"`
	Depth     string   `json:"depth"`
	DateRange string   `json:"date_range"`
	Sources   []string `json:"sources"`
	OutputDir string   `json:"output_dir"`
	Phase     string   `json:"phase"`
	Model     string   `json:"model"`
}

func (deepResearchCap) Execute(ctx context.Context, call *capabilities.Call) (*capabilities.Result, error) {
	var a deepResearchArgs
	if err := json.Unmarshal(call.Args, &a); err != nil {
		return nil, fmt.Errorf("deep_research: parse args: %w", err)
	}
	if a.Topic == "" {
		return nil, fmt.Errorf("deep_research: 'topic' is required")
	}
	if a.Intent == "" {
		return nil, fmt.Errorf("deep_research: 'intent' is required")
	}
	if !venvReady() {
		return nil, errors.New("deep_research: " + venvMissingMessage)
	}

	if a.OutputDir != "" {
		a.OutputDir = resolvePath(call.WorkDir, a.OutputDir)
	}

	// The capability is R-tier (research is read-only), but output_dir makes
	// it write report files — gate that specific case through the permission
	// callback rather than promoting the whole capability to W.
	if a.OutputDir != "" && call.RequestPermission != nil {
		ok, err := call.RequestPermission(ctx, fmt.Sprintf("deep_research will write report files into %s", a.OutputDir))
		if err != nil {
			return nil, fmt.Errorf("deep_research: permission check: %w", err)
		}
		if !ok {
			return nil, errors.New("deep_research: permission to write report files denied; re-run without 'output_dir' for an in-conversation report")
		}
	}

	// Note: the MCP surface pre-checks for code-only local models via gRPC
	// routing metadata; natively the dispatch engine owns model selection, so
	// that probe is skipped here.
	activity := newActivityReporter(call, "deep_research", "research")
	activity.Started(fmt.Sprintf("deep research start: topic=%q depth=%s phase=%s", a.Topic, defaultLabel(a.Depth, "standard"), defaultLabel(a.Phase, "all")))
	activity.Prompt(fmt.Sprintf("Topic: %s\nIntent: %s", a.Topic, a.Intent))

	model := &dispatchModelCaller{call: call, source: "deep_research", model: a.Model, tier: config.TierFastLightText}
	scriptPath, err := searchScriptPath()
	if err != nil {
		return nil, fmt.Errorf("deep_research: search script: %w", err)
	}
	searcher := web.NewSearcher(config.VenvPython(), scriptPath)
	dispatcher := research.NewSearchDispatcher(&researchSearchAdapter{searcher: searcher})
	pipeline := research.NewPipeline(model, dispatcher, &researchFetchAdapter{fetcher: web.NewFetcher()})

	activity.Progress("planning sources and research phases…")
	phaseResult, err := pipeline.Run(ctx, research.RunConfig{
		Topic:      a.Topic,
		Intent:     a.Intent,
		Depth:      a.Depth,
		DateRange:  a.DateRange,
		Sources:    a.Sources,
		OutputDir:  a.OutputDir,
		ProjectDir: call.WorkDir,
		Phase:      a.Phase,
		Progress: func(state research.ProgressState) {
			activity.Progress(formatDeepResearchProgress(state))
		},
	})
	if err != nil {
		activity.Failed(err)
		return nil, fmt.Errorf("deep_research: %w", err)
	}
	activity.Done(fmt.Sprintf("deep research complete: phase=%s next=%s", phaseResult.Phase, defaultLabel(phaseResult.NextPhase, "none")))

	out := capabilities.NewTextResult(phaseResult.Summary)
	if phaseResult.SuggestedNext != nil {
		if hint, err := json.Marshal(phaseResult.SuggestedNext); err == nil {
			out.Note = "suggested_next: " + string(hint)
		}
	}
	return out, nil
}

func formatDeepResearchProgress(state research.ProgressState) string {
	phase := strings.TrimSpace(state.Phase)
	if phase == "" {
		phase = "research"
	}
	var b strings.Builder
	b.WriteString(phase)
	if state.Total > 0 {
		b.WriteString(fmt.Sprintf(" %d/%d", state.Current, state.Total))
	}
	if state.Step != "" {
		b.WriteString(": ")
		b.WriteString(state.Step)
	}
	if state.FindingsAccepted > 0 {
		b.WriteString(fmt.Sprintf(" (%d findings accepted)", state.FindingsAccepted))
	}
	return b.String()
}

func defaultLabel(s, fallback string) string {
	s = strings.TrimSpace(s)
	if s == "" {
		return fallback
	}
	return s
}

